        da3_6 = fmaf(0.385758375f, dv3 * a3_5, da3_6);
        da3_6 = fmaf(-0.545544726f, dv2 * a3_6, da3_6);
    }
    if (c < nl0) dA1.p[0][(int64_t)i * nl0 + c] = da0_0;
    if (c < nl1) { float* d1 = dA1.p[1] + (int64_t)i * 3 * nl1 + c; d1[0] = da1_0; d1[nl1] = da1_1; d1[2 * nl1] = da1_2; }
    if (c < nl2) { float* d2 = dA1.p[2] + (int64_t)i * 5 * nl2 + c; d2[0] = da2_0; d2[nl2] = da2_1; d2[2 * nl2] = da2_2; d2[3 * nl2] = da2_3; d2[4 * nl2] = da2_4; }
    if (c < nl3) { float* d3 = dA1.p[3] + (int64_t)i * 7 * nl3 + c; d3[0] = da3_0; d3[nl3] = da3_1; d3[2 * nl3] = da3_2; d3[3 * nl3] = da3_3; d3[4 * nl3] = da3_4; d3[5 * nl3] = da3_5; d3[6 * nl3] = da3_6; }
}

// =================================================================================================
// Fast l<=2 real spherical harmonics (matches edge_sh16[:9] exactly, half the FLOPs)
// =================================================================================================
__device__ __forceinline__ void edge_sh9(float x, float y, float z, float r, float* __restrict__ Y) {
    const float inv_r = 1.0f / r;
    const float ux = x * inv_r, uy = y * inv_r, uz = z * inv_r;
    Y[0] = 1.0f;
    constexpr float S3  = 1.7320508075688772935f;
    constexpr float S15 = 3.8729833462074168852f;
    constexpr float S5  = 2.2360679774997896964f;
    Y[1] = S3 * ux;
    Y[2] = S3 * uy;
    Y[3] = S3 * uz;
    Y[4] = S15 * ux * uz;
    Y[5] = S15 * ux * uy;
    Y[6] = 0.5f * S5 * (3.0f * uy * uy - 1.0f);
    Y[7] = S15 * uy * uz;
    Y[8] = 0.5f * S15 * (uz * uz - ux * ux);
}

// Specialized L2 Edge Forward: lfeat2=2, lout2=2, lmsg=1 (N_OUT=21)
template <int SUBWARP, int NB_MAX, bool REM_BF, bool SMEM_C, bool DUAL_G = false>
__global__ void __launch_bounds__(128) ilmlip_l2_edge_fwd_lf2_m1_kernel(
    int N, int S, int n_base2, int n_base1, int n_msg,
    Int4 l2_c, ChebParam r_max2, ChebParam r_max1, float a0_over_sig1, float inv_DA2_sig1_kap_sq,
    const int* __restrict__ row_ptr, const int* __restrict__ row_end, const int* __restrict__ senders,
    const float4* __restrict__ vec_len, const int* __restrict__ species,
    const float* __restrict__ C2, const float* __restrict__ Cbf,
    const float* __restrict__ f0, CPtr4 I_node, Ptr4 A2, float* __restrict__ f1_out) {
    constexpr int NSUB = 128 / SUBWARP;
    constexpr int EBATCH = (SUBWARP == 32) ? 8 : 4;
    constexpr int NB_STRIDE = NB_MAX + 1;
    constexpr int NB1_STRIDE = DUAL_G ? 17 : 1;
    extern __shared__ float smem_c[];
    __shared__ float s_g[NSUB][EBATCH][NB_STRIDE];
    __shared__ float s_g1[DUAL_G ? NSUB : 1][DUAL_G ? EBATCH : 1][NB1_STRIDE];
    __shared__ float s_Y[NSUB][EBATCH][9];
    __shared__ int   s_j[NSUB][EBATCH];
    __shared__ int   s_pair[NSUB][EBATCH];
    __shared__ float s_f0[NSUB][EBATCH];

    const int l2_tot_cols = 3 * n_msg;
    const int bf_tot_cols = 2 * n_msg;
    const int c2_elems = S * S * n_base2 * l2_tot_cols;
    const int cbf_elems = REM_BF ? (S * S * n_base1 * bf_tot_cols) : 0;
    constexpr bool F4_SMEM = SMEM_C && (NB_MAX == 8) && !DUAL_G;
    float4* smem_c4 = reinterpret_cast<float4*>(smem_c);
    float4* smem_bf4 = smem_c4 + (size_t)S * S * 6 * SUBWARP;
    if constexpr (F4_SMEM) {
        const int n_c2_slots = S * S * 3 * SUBWARP;
        for (int idx = threadIdx.x; idx < n_c2_slots; idx += 128) {
            const int q = idx & (SUBWARP - 1);
            const int pl = idx / SUBWARP; const int pair = pl / 3; const int l = pl - pair * 3;
            float4 v0 = make_float4(0.f,0.f,0.f,0.f), v1 = make_float4(0.f,0.f,0.f,0.f);
            if (q < n_msg) {
                const float* src = C2 + (int64_t)pair * 8 * l2_tot_cols + l * n_msg + q;
                v0 = make_float4(__ldg(src), __ldg(src + l2_tot_cols), __ldg(src + 2*l2_tot_cols), __ldg(src + 3*l2_tot_cols));
                v1 = make_float4(__ldg(src + 4*l2_tot_cols), __ldg(src + 5*l2_tot_cols), __ldg(src + 6*l2_tot_cols), __ldg(src + 7*l2_tot_cols));
            }
            smem_c4[(pair * 6 + l * 2 + 0) * SUBWARP + q] = v0;
            smem_c4[(pair * 6 + l * 2 + 1) * SUBWARP + q] = v1;
        }
        if constexpr (REM_BF) {
            const int n_bf_slots = S * S * 2 * SUBWARP;
            for (int idx = threadIdx.x; idx < n_bf_slots; idx += 128) {
                const int q = idx & (SUBWARP - 1);
                const int pl = idx / SUBWARP; const int pair = pl / 2; const int l = pl - pair * 2;
                float4 v0 = make_float4(0.f,0.f,0.f,0.f), v1 = make_float4(0.f,0.f,0.f,0.f);
                if (q < n_msg) {
                    const float* src = Cbf + (int64_t)pair * 8 * bf_tot_cols + l * n_msg + q;
                    v0 = make_float4(__ldg(src), __ldg(src + bf_tot_cols), __ldg(src + 2*bf_tot_cols), __ldg(src + 3*bf_tot_cols));
                    v1 = make_float4(__ldg(src + 4*bf_tot_cols), __ldg(src + 5*bf_tot_cols), __ldg(src + 6*bf_tot_cols), __ldg(src + 7*bf_tot_cols));
                }
                smem_bf4[(pair * 4 + l * 2 + 0) * SUBWARP + q] = v0;
                smem_bf4[(pair * 4 + l * 2 + 1) * SUBWARP + q] = v1;
            }
        }
        __syncthreads();
    } else if constexpr (SMEM_C) {
        for (int idx = threadIdx.x; idx < c2_elems; idx += 128) smem_c[idx] = __ldg(C2 + idx);
        if constexpr (REM_BF) {
            float* smem_bf = smem_c + c2_elems;
            for (int idx = threadIdx.x; idx < cbf_elems; idx += 128) smem_bf[idx] = __ldg(Cbf + idx);
        }
        __syncthreads();
    }
    const int sid = threadIdx.x / SUBWARP;
    const int slane = threadIdx.x & (SUBWARP - 1);
    const unsigned smask = (SUBWARP == 8) ? (0xffu << ((sid & 3) * 8)) : ((SUBWARP == 16) ? ((sid & 1) ? 0xffff0000u : 0x0000ffffu) : 0xffffffffu);
    const int i = blockIdx.x * NSUB + sid;
    if (i >= N) return;
    const int z_i = species[i];
    const int eb = row_ptr[i], ee = row_end[i];
    const bool active_q = (slane < n_msg);
    const float* C2_base = SMEM_C ? smem_c : C2;
    const float* Cbf_base = REM_BF ? (SMEM_C ? (smem_c + c2_elems) : Cbf) : nullptr;

    float acc[21];
    #pragma unroll
    for (int k = 0; k < 21; ++k) acc[k] = 0.0f;

    for (int eb_b = eb; eb_b < ee; eb_b += EBATCH) {
        const int bcnt = (ee - eb_b < EBATCH) ? (ee - eb_b) : EBATCH;
        if (slane < bcnt) {
            const int e = eb_b + slane;
            const float4 vl = __ldg(vec_len + e);
            const int j = __ldg(senders + e);
            const float r = fmaxf(vl.w, 1e-8f);
            s_j[sid][slane] = j;
            s_pair[sid][slane] = z_i * S + __ldg(species + j);
            if constexpr (REM_BF) s_f0[sid][slane] = __ldg(f0 + j);
            if constexpr (NB_MAX == 8) {
                float4 g03, g47, d0, d1;
                eval_cheb8_f4<false>(r, r_max2, g03, g47, d0, d1);
                float* dst = s_g[sid][slane];
                dst[0]=g03.x; dst[1]=g03.y; dst[2]=g03.z; dst[3]=g03.w;
                dst[4]=g47.x; dst[5]=g47.y; dst[6]=g47.z; dst[7]=g47.w;
            } else {
                eval_cheb<false>(r, r_max2, n_base2, s_g[sid][slane], nullptr);
            }
            if constexpr (DUAL_G && REM_BF && SUBWARP == 8) {
                eval_cheb<false>(r, r_max1, n_base1, s_g1[sid][slane], nullptr);
            }
        } else if (slane >= EBATCH && slane < EBATCH + bcnt) {
            const int bi = slane - EBATCH;
            const float4 vl = __ldg(vec_len + eb_b + bi);
            const float r = fmaxf(vl.w, 1e-8f);
            edge_sh9(vl.x, vl.y, vl.z, r, s_Y[sid][bi]);
        } else if constexpr (DUAL_G && REM_BF && SUBWARP >= 16) {
            if (slane >= 2 * EBATCH && slane < 2 * EBATCH + bcnt) {
                const int bi = slane - 2 * EBATCH;
                const float4 vl = __ldg(vec_len + eb_b + bi);
                const float r = fmaxf(vl.w, 1e-8f);
                eval_cheb<false>(r, r_max1, n_base1, s_g1[sid][bi], nullptr);
            }
        }
        __syncwarp(smask);

        if (active_q) {
            for (int bi = 0; bi < bcnt; ++bi) {
                const int j = s_j[sid][bi];
                const int pair = s_pair[sid][bi];
                const float* gk = s_g[sid][bi];
                const float* Yk = s_Y[sid][bi];
                const float* C2p = C2_base + (int64_t)pair * n_base2 * l2_tot_cols + slane;
                float r2_0 = 0.0f, r2_1 = 0.0f, r2_2 = 0.0f;
                if constexpr (F4_SMEM) {
                    const float4 g03 = make_float4(gk[0], gk[1], gk[2], gk[3]);
                    const float4 g47 = make_float4(gk[4], gk[5], gk[6], gk[7]);
                    const float4* cp4 = smem_c4 + pair * 6 * SUBWARP + slane;
                    r2_0 = v1_dot4(cp4[0 * SUBWARP], g03) + v1_dot4(cp4[1 * SUBWARP], g47);
                    r2_1 = v1_dot4(cp4[2 * SUBWARP], g03) + v1_dot4(cp4[3 * SUBWARP], g47);
                    r2_2 = v1_dot4(cp4[4 * SUBWARP], g03) + v1_dot4(cp4[5 * SUBWARP], g47);
                } else {
                    auto acc_c2 = [&](int k) {
                        const float gv = gk[k]; const float* rrow = C2p + k * l2_tot_cols;
                        r2_0 = fmaf(SMEM_C ? rrow[0]         : __ldg(rrow),           gv, r2_0);
                        r2_1 = fmaf(SMEM_C ? rrow[n_msg]     : __ldg(rrow + n_msg),   gv, r2_1);
                        r2_2 = fmaf(SMEM_C ? rrow[2 * n_msg] : __ldg(rrow + 2*n_msg), gv, r2_2);
                    };
                    if constexpr (NB_MAX == 8) {
                        #pragma unroll
                        for (int k = 0; k < 8; ++k) acc_c2(k);
                    } else {
                        if (n_base2 == 12)      {
                            #pragma unroll 4
                            for (int k = 0; k < 12; ++k) acc_c2(k); }
                        else if (n_base2 == 14) {
                            #pragma unroll 4
                            for (int k = 0; k < 14; ++k) acc_c2(k); }
                        else if (n_base2 == 16) {
                            #pragma unroll 4
                            for (int k = 0; k < 16; ++k) acc_c2(k); }
                        else { for (int k = 0; k < n_base2; ++k) acc_c2(k); }
                    }
                }

                float rbf0 = 0.0f, rbf1 = 0.0f;
                if constexpr (REM_BF) {
                    const float f0_j = s_f0[sid][bi];
                    if constexpr (F4_SMEM) {
                        const float4 g03 = make_float4(gk[0], gk[1], gk[2], gk[3]);
                        const float4 g47 = make_float4(gk[4], gk[5], gk[6], gk[7]);
                        const float4* bp4 = smem_bf4 + pair * 4 * SUBWARP + slane;
                        rbf0 = v1_dot4(bp4[0 * SUBWARP], g03) + v1_dot4(bp4[1 * SUBWARP], g47);
                        rbf1 = v1_dot4(bp4[2 * SUBWARP], g03) + v1_dot4(bp4[3 * SUBWARP], g47);
                    } else {
                        const float* gkb = DUAL_G ? s_g1[sid][bi] : gk;
                        const float* Cbp = Cbf_base + (int64_t)pair * n_base1 * bf_tot_cols + slane;
                        auto acc_bf = [&](int k) {
                            const float gv = gkb[k]; const float* rrow = Cbp + k * bf_tot_cols;
                            rbf0 = fmaf(SMEM_C ? rrow[0]     : __ldg(rrow),         gv, rbf0);
                            rbf1 = fmaf(SMEM_C ? rrow[n_msg] : __ldg(rrow + n_msg), gv, rbf1);
                        };
                        if constexpr (!DUAL_G && NB_MAX == 8) {
                            #pragma unroll
                            for (int k = 0; k < 8; ++k) acc_bf(k);
                        } else {
                            if (n_base1 == 8)       {
                                #pragma unroll
                                for (int k = 0; k < 8; ++k) acc_bf(k); }
                            else if (n_base1 == 12) {
                                #pragma unroll 4
                                for (int k = 0; k < 12; ++k) acc_bf(k); }
                            else if (n_base1 == 14) {
                                #pragma unroll 4
                                for (int k = 0; k < 14; ++k) acc_bf(k); }
                            else if (n_base1 == 16) {
                                #pragma unroll 4
                                for (int k = 0; k < 16; ++k) acc_bf(k); }
                            else { for (int k = 0; k < n_base1; ++k) acc_bf(k); }
                        }
                    }
                    rbf0 *= f0_j; rbf1 *= f0_j;
                }
                const float i0_0 = __ldg(I_node.p[0] + (int64_t)j * n_msg + slane) - (REM_BF ? rbf0 * Yk[0] : 0.0f);
                const float* pI1 = I_node.p[1] + (int64_t)j * 3 * n_msg + slane;
                const float i1_0 = __ldg(pI1)           - (REM_BF ? rbf1 * Yk[1] : 0.0f);
                const float i1_1 = __ldg(pI1 + n_msg)   - (REM_BF ? rbf1 * Yk[2] : 0.0f);
                const float i1_2 = __ldg(pI1 + 2*n_msg) - (REM_BF ? rbf1 * Yk[3] : 0.0f);
                const float p0_0 = r2_0 * Yk[0];
                const float p1_0 = r2_1 * Yk[1], p1_1 = r2_1 * Yk[2], p1_2 = r2_1 * Yk[3];
                const float p2_0 = r2_2 * Yk[4], p2_1 = r2_2 * Yk[5], p2_2 = r2_2 * Yk[6], p2_3 = r2_2 * Yk[7], p2_4 = r2_2 * Yk[8];
                acc[0] = fmaf(p0_0, i0_0, acc[0]);
                acc[1] = fmaf(0.577350269f, p1_0 * i1_0, acc[1]);
                acc[1] = fmaf(0.577350269f, p1_1 * i1_1, acc[1]);
                acc[1] = fmaf(0.577350269f, p1_2 * i1_2, acc[1]);
                acc[2] = fmaf(p0_0, i1_0, acc[2]);
                acc[3] = fmaf(p0_0, i1_1, acc[3]);
                acc[4] = fmaf(p0_0, i1_2, acc[4]);
                acc[5] = fmaf(p1_0, i0_0, acc[5]);
                acc[6] = fmaf(p1_1, i0_0, acc[6]);
                acc[7] = fmaf(p1_2, i0_0, acc[7]);
                acc[8] = fmaf(0.547722558f, p2_0 * i1_2, acc[8]);
                acc[8] = fmaf(0.547722558f, p2_1 * i1_1, acc[8]);
                acc[8] = fmaf(-0.316227766f, p2_2 * i1_0, acc[8]);
                acc[8] = fmaf(-0.547722558f, p2_4 * i1_0, acc[8]);
                acc[9] = fmaf(0.547722558f, p2_1 * i1_0, acc[9]);
                acc[9] = fmaf(0.632455532f, p2_2 * i1_1, acc[9]);
                acc[9] = fmaf(0.547722558f, p2_3 * i1_2, acc[9]);
                acc[10] = fmaf(0.547722558f, p2_0 * i1_0, acc[10]);
                acc[10] = fmaf(-0.316227766f, p2_2 * i1_2, acc[10]);
                acc[10] = fmaf(0.547722558f, p2_3 * i1_1, acc[10]);
                acc[10] = fmaf(0.547722558f, p2_4 * i1_2, acc[10]);
                acc[11] = fmaf(0.707106781f, p1_0 * i1_2, acc[11]);
                acc[11] = fmaf(0.707106781f, p1_2 * i1_0, acc[11]);
                acc[12] = fmaf(0.707106781f, p1_0 * i1_1, acc[12]);
                acc[12] = fmaf(0.707106781f, p1_1 * i1_0, acc[12]);
                acc[13] = fmaf(-0.40824829f, p1_0 * i1_0, acc[13]);
                acc[13] = fmaf(0.816496581f, p1_1 * i1_1, acc[13]);
                acc[13] = fmaf(-0.40824829f, p1_2 * i1_2, acc[13]);
                acc[14] = fmaf(0.707106781f, p1_1 * i1_2, acc[14]);
                acc[14] = fmaf(0.707106781f, p1_2 * i1_1, acc[14]);
                acc[15] = fmaf(-0.707106781f, p1_0 * i1_0, acc[15]);
                acc[15] = fmaf(0.707106781f, p1_2 * i1_2, acc[15]);
                acc[16] = fmaf(p2_0, i0_0, acc[16]);
                acc[17] = fmaf(p2_1, i0_0, acc[17]);
                acc[18] = fmaf(p2_2, i0_0, acc[18]);
                acc[19] = fmaf(p2_3, i0_0, acc[19]);
                acc[20] = fmaf(p2_4, i0_0, acc[20]);
            }
        }
        __syncwarp(smask);
    }

    float sq_lane = 0.0f;
    if (active_q) {
        #pragma unroll
        for (int k = 0; k < 21; ++k) sq_lane = fmaf(acc[k], acc[k], sq_lane); }
    const float sq_tot = (SUBWARP == 8) ? qwarp_sum_f(sq_lane, smask) : ((SUBWARP == 16) ? half_warp_sum_f(sq_lane, smask) : warp_sum_f(sq_lane));
    const float f1 = a0_over_sig1 / sqrtf(1.0f + sq_tot * inv_DA2_sig1_kap_sq);
    if (slane == 0) f1_out[i] = f1;
    if (active_q) {
        const int c0 = l2_c.v[0], c1 = l2_c.v[1], c2 = l2_c.v[2];
        float* d0 = A2.p[0] + (int64_t)i * c0 + slane;
        float* d1 = A2.p[1] + (int64_t)i * 3 * c1 + slane;
        float* d2 = A2.p[2] + (int64_t)i * 5 * c2 + slane;
        d0[0 * n_msg] = acc[0] * f1;
        d0[1 * n_msg] = acc[1] * f1;
        d1[0 * c1 + 0 * n_msg] = acc[2] * f1;
        d1[1 * c1 + 0 * n_msg] = acc[3] * f1;
        d1[2 * c1 + 0 * n_msg] = acc[4] * f1;
        d1[0 * c1 + 1 * n_msg] = acc[5] * f1;
        d1[1 * c1 + 1 * n_msg] = acc[6] * f1;
        d1[2 * c1 + 1 * n_msg] = acc[7] * f1;
        d1[0 * c1 + 2 * n_msg] = acc[8] * f1;
        d1[1 * c1 + 2 * n_msg] = acc[9] * f1;
        d1[2 * c1 + 2 * n_msg] = acc[10] * f1;
        d2[0 * c2 + 0 * n_msg] = acc[11] * f1;
        d2[1 * c2 + 0 * n_msg] = acc[12] * f1;
        d2[2 * c2 + 0 * n_msg] = acc[13] * f1;
        d2[3 * c2 + 0 * n_msg] = acc[14] * f1;
        d2[4 * c2 + 0 * n_msg] = acc[15] * f1;
        d2[0 * c2 + 1 * n_msg] = acc[16] * f1;
        d2[1 * c2 + 1 * n_msg] = acc[17] * f1;
        d2[2 * c2 + 1 * n_msg] = acc[18] * f1;
        d2[3 * c2 + 1 * n_msg] = acc[19] * f1;
        d2[4 * c2 + 1 * n_msg] = acc[20] * f1;
    }
}

template <int SUBWARP>
__global__ void __launch_bounds__(128) ilmlip_gate_bwd_pack_l2_lf2_m1_kernel(
    int N, int n_msg, Int4 l2_c, float inv_DA2_a0_kap_sq,
    CPtr4 A2, CPtr4 dA2, const float* __restrict__ f1_arr, float* __restrict__ dA2_pack) {
    constexpr int NSUB = 128 / SUBWARP;
    const int sid = threadIdx.x / SUBWARP;
    const int slane = threadIdx.x & (SUBWARP - 1);
    const unsigned smask = (SUBWARP == 8) ? (0xffu << ((sid & 3) * 8)) : ((SUBWARP == 16) ? ((sid & 1) ? 0xffff0000u : 0x0000ffffu) : 0xffffffffu);
    const int i = blockIdx.x * NSUB + sid;
    if (i >= N) return;
    const bool active_q = (slane < n_msg);
    float av[24], dv[24];
    av[21] = 0.0f; dv[21] = 0.0f;
    av[22] = 0.0f; dv[22] = 0.0f;
    av[23] = 0.0f; dv[23] = 0.0f;
    float dot_lane = 0.0f;
    if (active_q) {
        const int c0 = l2_c.v[0], c1 = l2_c.v[1], c2 = l2_c.v[2];
        const float* pA0 = A2.p[0] + (int64_t)i * c0 + slane; const float* pdA0 = dA2.p[0] + (int64_t)i * c0 + slane;
        const float* pA1 = A2.p[1] + (int64_t)i * 3 * c1 + slane; const float* pdA1 = dA2.p[1] + (int64_t)i * 3 * c1 + slane;
        const float* pA2 = A2.p[2] + (int64_t)i * 5 * c2 + slane; const float* pdA2 = dA2.p[2] + (int64_t)i * 5 * c2 + slane;
        av[0] = pA0[0 * n_msg]; dv[0] = pdA0[0 * n_msg];
        av[1] = pA0[1 * n_msg]; dv[1] = pdA0[1 * n_msg];
        av[2] = pA1[0 * c1 + 0 * n_msg]; dv[2] = pdA1[0 * c1 + 0 * n_msg];
        av[3] = pA1[1 * c1 + 0 * n_msg]; dv[3] = pdA1[1 * c1 + 0 * n_msg];
        av[4] = pA1[2 * c1 + 0 * n_msg]; dv[4] = pdA1[2 * c1 + 0 * n_msg];
        av[5] = pA1[0 * c1 + 1 * n_msg]; dv[5] = pdA1[0 * c1 + 1 * n_msg];
        av[6] = pA1[1 * c1 + 1 * n_msg]; dv[6] = pdA1[1 * c1 + 1 * n_msg];
        av[7] = pA1[2 * c1 + 1 * n_msg]; dv[7] = pdA1[2 * c1 + 1 * n_msg];
        av[8] = pA1[0 * c1 + 2 * n_msg]; dv[8] = pdA1[0 * c1 + 2 * n_msg];
        av[9] = pA1[1 * c1 + 2 * n_msg]; dv[9] = pdA1[1 * c1 + 2 * n_msg];
        av[10] = pA1[2 * c1 + 2 * n_msg]; dv[10] = pdA1[2 * c1 + 2 * n_msg];
        av[11] = pA2[0 * c2 + 0 * n_msg]; dv[11] = pdA2[0 * c2 + 0 * n_msg];
        av[12] = pA2[1 * c2 + 0 * n_msg]; dv[12] = pdA2[1 * c2 + 0 * n_msg];
        av[13] = pA2[2 * c2 + 0 * n_msg]; dv[13] = pdA2[2 * c2 + 0 * n_msg];
        av[14] = pA2[3 * c2 + 0 * n_msg]; dv[14] = pdA2[3 * c2 + 0 * n_msg];
        av[15] = pA2[4 * c2 + 0 * n_msg]; dv[15] = pdA2[4 * c2 + 0 * n_msg];
        av[16] = pA2[0 * c2 + 1 * n_msg]; dv[16] = pdA2[0 * c2 + 1 * n_msg];
        av[17] = pA2[1 * c2 + 1 * n_msg]; dv[17] = pdA2[1 * c2 + 1 * n_msg];
        av[18] = pA2[2 * c2 + 1 * n_msg]; dv[18] = pdA2[2 * c2 + 1 * n_msg];
        av[19] = pA2[3 * c2 + 1 * n_msg]; dv[19] = pdA2[3 * c2 + 1 * n_msg];
        av[20] = pA2[4 * c2 + 1 * n_msg]; dv[20] = pdA2[4 * c2 + 1 * n_msg];
        #pragma unroll
        for (int k = 0; k < 21; ++k) dot_lane = fmaf(av[k], dv[k], dot_lane);
    }
    const float dot = (SUBWARP == 8) ? qwarp_sum_f(dot_lane, smask) : ((SUBWARP == 16) ? half_warp_sum_f(dot_lane, smask) : warp_sum_f(dot_lane));
    const float f1 = f1_arr[i];
    const float sc = (dot * f1) * inv_DA2_a0_kap_sq;
    if (active_q) {
        float4* dst4 = reinterpret_cast<float4*>(dA2_pack) + (int64_t)i * (6 * SUBWARP) + slane;
        dst4[0 * SUBWARP] = make_float4(fmaf(f1, dv[0], -sc * av[0]), fmaf(f1, dv[1], -sc * av[1]), fmaf(f1, dv[2], -sc * av[2]), fmaf(f1, dv[3], -sc * av[3]));
        dst4[1 * SUBWARP] = make_float4(fmaf(f1, dv[4], -sc * av[4]), fmaf(f1, dv[5], -sc * av[5]), fmaf(f1, dv[6], -sc * av[6]), fmaf(f1, dv[7], -sc * av[7]));
        dst4[2 * SUBWARP] = make_float4(fmaf(f1, dv[8], -sc * av[8]), fmaf(f1, dv[9], -sc * av[9]), fmaf(f1, dv[10], -sc * av[10]), fmaf(f1, dv[11], -sc * av[11]));
        dst4[3 * SUBWARP] = make_float4(fmaf(f1, dv[12], -sc * av[12]), fmaf(f1, dv[13], -sc * av[13]), fmaf(f1, dv[14], -sc * av[14]), fmaf(f1, dv[15], -sc * av[15]));
        dst4[4 * SUBWARP] = make_float4(fmaf(f1, dv[16], -sc * av[16]), fmaf(f1, dv[17], -sc * av[17]), fmaf(f1, dv[18], -sc * av[18]), fmaf(f1, dv[19], -sc * av[19]));
        dst4[5 * SUBWARP] = make_float4(fmaf(f1, dv[20], -sc * av[20]), 0.0f, 0.0f, 0.0f);
    }
}

// Specialized SENDER-OWNED ZERO-ATOMIC L2 Edge Backward: lfeat2=2, lout2=2, lmsg=1 (N_OUT=21, N_VEC4=6)
template <int SUBWARP, int NB_MAX, bool REM_BF, bool STRESS, bool F32_F, bool SMEM_C, bool DUAL_G = false>
__global__ void __launch_bounds__(128, 4) ilmlip_l2_edge_bwd_lf2_m1_sender_kernel(
    int N, int S, int n_base2, int n_base1, int n_msg, ChebParam r_max2, ChebParam r_max1,
    const int* __restrict__ row_ptr, const int* __restrict__ row_end, const int* __restrict__ senders,
    const float4* __restrict__ vec_len, const int* __restrict__ species,
    const float* __restrict__ C2, const float* __restrict__ Cbf,
    const float* __restrict__ f0, CPtr4 I_node, const float* __restrict__ dA2_pack,
    Ptr4 dI_node, float* __restrict__ df0_bf,
    double* __restrict__ forces, float* __restrict__ forces_f32, double* __restrict__ virial) {
    using FT = typename std::conditional<F32_F, float, double>::type;
    constexpr int NSUB = 128 / SUBWARP;
    constexpr int EBATCH = (SUBWARP == 32) ? 8 : 4;
    constexpr int NB_STRIDE = NB_MAX + 1;
    constexpr int NB1_STRIDE = DUAL_G ? 17 : 1;
    extern __shared__ float smem_c[];
    __shared__ float  s_g[NSUB][EBATCH][NB_STRIDE];
    __shared__ float  s_dg[NSUB][EBATCH][NB_STRIDE];
    __shared__ float  s_g1[DUAL_G ? NSUB : 1][DUAL_G ? EBATCH : 1][NB1_STRIDE];
    __shared__ float  s_dg1[DUAL_G ? NSUB : 1][DUAL_G ? EBATCH : 1][NB1_STRIDE];
    __shared__ float  s_Y[NSUB][EBATCH][9];
    __shared__ float4 s_vl[NSUB][EBATCH];
    __shared__ int    s_i[NSUB][EBATCH];
    __shared__ int    s_pair[NSUB][EBATCH];
    __shared__ float  s_er_dY[NSUB][EBATCH][9];
    __shared__ FT     s_sf[NSUB][3];

    const int l2_tot_cols = 3 * n_msg;
    const int bf_tot_cols = 2 * n_msg;
    const int c2_elems = S * S * n_base2 * l2_tot_cols;
    const int cbf_elems = REM_BF ? (S * S * n_base1 * bf_tot_cols) : 0;
    constexpr bool F4_SMEM = SMEM_C && (NB_MAX == 8) && !DUAL_G;
    float4* smem_c4 = reinterpret_cast<float4*>(smem_c);
    float4* smem_bf4 = smem_c4 + (size_t)S * S * 6 * SUBWARP;
    if constexpr (F4_SMEM) {
        const int n_c2_slots = S * S * 3 * SUBWARP;
        for (int idx = threadIdx.x; idx < n_c2_slots; idx += 128) {
            const int q = idx & (SUBWARP - 1);
            const int pl = idx / SUBWARP; const int pair = pl / 3; const int l = pl - pair * 3;
            float4 v0 = make_float4(0.f,0.f,0.f,0.f), v1 = make_float4(0.f,0.f,0.f,0.f);
            if (q < n_msg) {
                const float* src = C2 + (int64_t)pair * 8 * l2_tot_cols + l * n_msg + q;
                v0 = make_float4(__ldg(src), __ldg(src + l2_tot_cols), __ldg(src + 2*l2_tot_cols), __ldg(src + 3*l2_tot_cols));
                v1 = make_float4(__ldg(src + 4*l2_tot_cols), __ldg(src + 5*l2_tot_cols), __ldg(src + 6*l2_tot_cols), __ldg(src + 7*l2_tot_cols));
            }
            smem_c4[(pair * 6 + l * 2 + 0) * SUBWARP + q] = v0;
            smem_c4[(pair * 6 + l * 2 + 1) * SUBWARP + q] = v1;
        }
        if constexpr (REM_BF) {
            const int n_bf_slots = S * S * 2 * SUBWARP;
            for (int idx = threadIdx.x; idx < n_bf_slots; idx += 128) {
                const int q = idx & (SUBWARP - 1);
                const int pl = idx / SUBWARP; const int pair = pl / 2; const int l = pl - pair * 2;
                float4 v0 = make_float4(0.f,0.f,0.f,0.f), v1 = make_float4(0.f,0.f,0.f,0.f);
                if (q < n_msg) {
                    const float* src = Cbf + (int64_t)pair * 8 * bf_tot_cols + l * n_msg + q;
                    v0 = make_float4(__ldg(src), __ldg(src + bf_tot_cols), __ldg(src + 2*bf_tot_cols), __ldg(src + 3*bf_tot_cols));
                    v1 = make_float4(__ldg(src + 4*bf_tot_cols), __ldg(src + 5*bf_tot_cols), __ldg(src + 6*bf_tot_cols), __ldg(src + 7*bf_tot_cols));
                }
                smem_bf4[(pair * 4 + l * 2 + 0) * SUBWARP + q] = v0;
                smem_bf4[(pair * 4 + l * 2 + 1) * SUBWARP + q] = v1;
            }
        }
        __syncthreads();
    } else if constexpr (SMEM_C) {
        for (int idx = threadIdx.x; idx < c2_elems; idx += 128) smem_c[idx] = __ldg(C2 + idx);
        if constexpr (REM_BF) {
            float* smem_bf = smem_c + c2_elems;
            for (int idx = threadIdx.x; idx < cbf_elems; idx += 128) smem_bf[idx] = __ldg(Cbf + idx);
        }
        __syncthreads();
    }
    const int sid = threadIdx.x / SUBWARP;
    const int slane = threadIdx.x & (SUBWARP - 1);
    const unsigned smask = (SUBWARP == 8) ? (0xffu << ((sid & 3) * 8)) : ((SUBWARP == 16) ? ((sid & 1) ? 0xffff0000u : 0x0000ffffu) : 0xffffffffu);
    const int j = blockIdx.x * NSUB + sid;
    if (j >= N) return;
    const int z_j = species[j];
    const int eb = row_ptr[j], ee = row_end[j];
    const bool active_q = (slane < n_msg);
    const float f0_j = REM_BF ? __ldg(f0 + j) : 0.0f;
    const float* C2_base = SMEM_C ? smem_c : C2;
    const float* Cbf_base = REM_BF ? (SMEM_C ? (smem_c + c2_elems) : Cbf) : nullptr;

    float i0_raw = 0.0f, i1_0_raw = 0.0f, i1_1_raw = 0.0f, i1_2_raw = 0.0f;
    if (active_q) {
        i0_raw = __ldg(I_node.p[0] + (int64_t)j * n_msg + slane);
        const float* pI1 = I_node.p[1] + (int64_t)j * 3 * n_msg + slane;
        i1_0_raw = __ldg(pI1); i1_1_raw = __ldg(pI1 + n_msg); i1_2_raw = __ldg(pI1 + 2 * n_msg);
    }
    if (slane < 3) s_sf[sid][slane] = (FT)0;
    float acc_di0 = 0.0f, acc_di1_0 = 0.0f, acc_di1_1 = 0.0f, acc_di1_2 = 0.0f;
    float acc_df0 = 0.0f;
    double v0 = 0.0, v1 = 0.0, v2 = 0.0, v3 = 0.0, v4 = 0.0, v5 = 0.0;

    for (int eb_b = eb; eb_b < ee; eb_b += EBATCH) {
        const int bcnt = (ee - eb_b < EBATCH) ? (ee - eb_b) : EBATCH;
        if (slane < bcnt) {
            const int e = eb_b + slane;
            const float4 vl_rev = __ldg(vec_len + e);
            const float4 vl_fwd = make_float4(-vl_rev.x, -vl_rev.y, -vl_rev.z, vl_rev.w);
            const int i_nb = __ldg(senders + e);
            const float r = fmaxf(vl_rev.w, 1e-8f);
            s_vl[sid][slane] = vl_fwd;
            s_i[sid][slane] = i_nb;
            s_pair[sid][slane] = __ldg(species + i_nb) * S + z_j;
            if constexpr (NB_MAX == 8) {
                float4 g03, g47, dg03, dg47;
                eval_cheb8_f4<true>(r, r_max2, g03, g47, dg03, dg47);
                float* gs = s_g[sid][slane]; float* dgs = s_dg[sid][slane];
                gs[0]=g03.x; gs[1]=g03.y; gs[2]=g03.z; gs[3]=g03.w; gs[4]=g47.x; gs[5]=g47.y; gs[6]=g47.z; gs[7]=g47.w;
                dgs[0]=dg03.x; dgs[1]=dg03.y; dgs[2]=dg03.z; dgs[3]=dg03.w; dgs[4]=dg47.x; dgs[5]=dg47.y; dgs[6]=dg47.z; dgs[7]=dg47.w;
            } else {
                eval_cheb<true>(r, r_max2, n_base2, s_g[sid][slane], s_dg[sid][slane]);
            }
            if constexpr (DUAL_G && REM_BF && SUBWARP == 8) {
                eval_cheb<true>(r, r_max1, n_base1, s_g1[sid][slane], s_dg1[sid][slane]);
            }
        } else if (slane >= EBATCH && slane < EBATCH + bcnt) {
            const int bi = slane - EBATCH;
            const float4 vl_rev = __ldg(vec_len + eb_b + bi);
            const float r = fmaxf(vl_rev.w, 1e-8f);
            edge_sh9(-vl_rev.x, -vl_rev.y, -vl_rev.z, r, s_Y[sid][bi]);
        } else if constexpr (DUAL_G && REM_BF && SUBWARP >= 16) {
            if (slane >= 2 * EBATCH && slane < 2 * EBATCH + bcnt) {
                const int bi = slane - 2 * EBATCH;
                const float4 vl_rev = __ldg(vec_len + eb_b + bi);
                const float r = fmaxf(vl_rev.w, 1e-8f);
                eval_cheb<true>(r, r_max1, n_base1, s_g1[sid][bi], s_dg1[sid][bi]);
            }
        }
        __syncwarp(smask);

        for (int bi = 0; bi < bcnt; ++bi) {
            const int i_nb = s_i[sid][bi];
            const int pair = s_pair[sid][bi];
            float er_lane = 0.0f;
            float dY1 = 0.0f, dY2 = 0.0f, dY3 = 0.0f, dY4 = 0.0f, dY5 = 0.0f, dY6 = 0.0f, dY7 = 0.0f, dY8 = 0.0f;
            if (active_q) {
                const float* gk  = s_g[sid][bi];
                const float* dgk = s_dg[sid][bi];
                const float* Yk  = s_Y[sid][bi];
                const float* C2p = C2_base + (int64_t)pair * n_base2 * l2_tot_cols + slane;
                float r2_0 = 0.0f, r2_1 = 0.0f, r2_2 = 0.0f;
                float dr2_0 = 0.0f, dr2_1 = 0.0f, dr2_2 = 0.0f;
                if constexpr (F4_SMEM) {
                    const float4 g03 = make_float4(gk[0], gk[1], gk[2], gk[3]);
                    const float4 g47 = make_float4(gk[4], gk[5], gk[6], gk[7]);
                    const float4 d03 = make_float4(dgk[0], dgk[1], dgk[2], dgk[3]);
                    const float4 d47 = make_float4(dgk[4], dgk[5], dgk[6], dgk[7]);
                    const float4* cp4 = smem_c4 + pair * 6 * SUBWARP + slane;
                    const float4 c0a = cp4[0 * SUBWARP], c0b = cp4[1 * SUBWARP];
                    r2_0 = v1_dot4(c0a, g03) + v1_dot4(c0b, g47); dr2_0 = v1_dot4(c0a, d03) + v1_dot4(c0b, d47);
                    const float4 c1a = cp4[2 * SUBWARP], c1b = cp4[3 * SUBWARP];
                    r2_1 = v1_dot4(c1a, g03) + v1_dot4(c1b, g47); dr2_1 = v1_dot4(c1a, d03) + v1_dot4(c1b, d47);
                    const float4 c2a = cp4[4 * SUBWARP], c2b = cp4[5 * SUBWARP];
                    r2_2 = v1_dot4(c2a, g03) + v1_dot4(c2b, g47); dr2_2 = v1_dot4(c2a, d03) + v1_dot4(c2b, d47);
                } else {
                    auto acc_c2 = [&](int k) {
                        const float gv = gk[k], dgv = dgk[k]; const float* rrow = C2p + k * l2_tot_cols;
                        const float c0 = SMEM_C ? rrow[0]         : __ldg(rrow);
                        const float c1 = SMEM_C ? rrow[n_msg]     : __ldg(rrow + n_msg);
                        const float c2 = SMEM_C ? rrow[2 * n_msg] : __ldg(rrow + 2 * n_msg);
                        r2_0 = fmaf(c0, gv, r2_0); dr2_0 = fmaf(c0, dgv, dr2_0);
                        r2_1 = fmaf(c1, gv, r2_1); dr2_1 = fmaf(c1, dgv, dr2_1);
                        r2_2 = fmaf(c2, gv, r2_2); dr2_2 = fmaf(c2, dgv, dr2_2);
                    };
                    if constexpr (NB_MAX == 8) {
                        #pragma unroll
                        for (int k = 0; k < 8; ++k) acc_c2(k);
                    } else {
                        if (n_base2 == 12)      {
                            #pragma unroll 4
                            for (int k = 0; k < 12; ++k) acc_c2(k); }
                        else if (n_base2 == 14) {
                            #pragma unroll 4
                            for (int k = 0; k < 14; ++k) acc_c2(k); }
                        else if (n_base2 == 16) {
                            #pragma unroll 4
                            for (int k = 0; k < 16; ++k) acc_c2(k); }
                        else { for (int k = 0; k < n_base2; ++k) acc_c2(k); }
                    }
                }

                float rbf0 = 0.0f, rbf1 = 0.0f, drbf0 = 0.0f, drbf1 = 0.0f;
                if constexpr (REM_BF) {
                    if constexpr (F4_SMEM) {
                        const float4 g03 = make_float4(gk[0], gk[1], gk[2], gk[3]);
                        const float4 g47 = make_float4(gk[4], gk[5], gk[6], gk[7]);
                        const float4 d03 = make_float4(dgk[0], dgk[1], dgk[2], dgk[3]);
                        const float4 d47 = make_float4(dgk[4], dgk[5], dgk[6], dgk[7]);
                        const float4* bp4 = smem_bf4 + pair * 4 * SUBWARP + slane;
                        const float4 b0a = bp4[0 * SUBWARP], b0b = bp4[1 * SUBWARP];
                        rbf0 = v1_dot4(b0a, g03) + v1_dot4(b0b, g47); drbf0 = v1_dot4(b0a, d03) + v1_dot4(b0b, d47);
                        const float4 b1a = bp4[2 * SUBWARP], b1b = bp4[3 * SUBWARP];
                        rbf1 = v1_dot4(b1a, g03) + v1_dot4(b1b, g47); drbf1 = v1_dot4(b1a, d03) + v1_dot4(b1b, d47);
                    } else {
                        const float* gkb  = DUAL_G ? s_g1[sid][bi]  : gk;
                        const float* dgkb = DUAL_G ? s_dg1[sid][bi] : dgk;
                        const float* Cbp = Cbf_base + (int64_t)pair * n_base1 * bf_tot_cols + slane;
                        auto acc_bf = [&](int k) {
                            const float gv = gkb[k], dgv = dgkb[k]; const float* rrow = Cbp + k * bf_tot_cols;
                            const float b0 = SMEM_C ? rrow[0]     : __ldg(rrow);
                            const float b1 = SMEM_C ? rrow[n_msg] : __ldg(rrow + n_msg);
                            rbf0 = fmaf(b0, gv, rbf0); drbf0 = fmaf(b0, dgv, drbf0);
                            rbf1 = fmaf(b1, gv, rbf1); drbf1 = fmaf(b1, dgv, drbf1);
                        };
                        if constexpr (!DUAL_G && NB_MAX == 8) {
                            #pragma unroll
                            for (int k = 0; k < 8; ++k) acc_bf(k);
                        } else {
                            if (n_base1 == 8)       {
                                #pragma unroll
                                for (int k = 0; k < 8; ++k) acc_bf(k); }
                            else if (n_base1 == 12) {
                                #pragma unroll 4
                                for (int k = 0; k < 12; ++k) acc_bf(k); }
                            else if (n_base1 == 14) {
                                #pragma unroll 4
                                for (int k = 0; k < 14; ++k) acc_bf(k); }
                            else if (n_base1 == 16) {
                                #pragma unroll 4
                                for (int k = 0; k < 16; ++k) acc_bf(k); }
                            else { for (int k = 0; k < n_base1; ++k) acc_bf(k); }
                        }
                    }
                }
                const float i0_0 = i0_raw   - (REM_BF ? (f0_j * rbf0) * Yk[0] : 0.0f);
                const float i1_0 = i1_0_raw - (REM_BF ? (f0_j * rbf1) * Yk[1] : 0.0f);
                const float i1_1 = i1_1_raw - (REM_BF ? (f0_j * rbf1) * Yk[2] : 0.0f);
                const float i1_2 = i1_2_raw - (REM_BF ? (f0_j * rbf1) * Yk[3] : 0.0f);
                const float p0_0 = r2_0 * Yk[0];
                const float p1_0 = r2_1 * Yk[1], p1_1 = r2_1 * Yk[2], p1_2 = r2_1 * Yk[3];
                const float p2_0 = r2_2 * Yk[4], p2_1 = r2_2 * Yk[5], p2_2 = r2_2 * Yk[6], p2_3 = r2_2 * Yk[7], p2_4 = r2_2 * Yk[8];
                float dp0_0 = 0.0f;
                float dp1_0 = 0.0f, dp1_1 = 0.0f, dp1_2 = 0.0f;
                float dp2_0 = 0.0f, dp2_1 = 0.0f, dp2_2 = 0.0f, dp2_3 = 0.0f, dp2_4 = 0.0f;
                float di0_0 = 0.0f;
                float di1_0 = 0.0f, di1_1 = 0.0f, di1_2 = 0.0f;
                const float4* p4 = reinterpret_cast<const float4*>(dA2_pack) + (int64_t)i_nb * (6 * SUBWARP) + slane;
                const float4 qv0 = __ldg(p4 + 0 * SUBWARP);
                { // (0,0)->0 slot 0
                    dp0_0 = fmaf(qv0.x, i0_0, dp0_0);
                    di0_0 = fmaf(qv0.x, p0_0, di0_0);
                }
                { // (1,1)->0 slot 1
                    dp1_0 = fmaf(0.577350269f, qv0.y * i1_0, dp1_0);
                    dp1_1 = fmaf(0.577350269f, qv0.y * i1_1, dp1_1);
                    dp1_2 = fmaf(0.577350269f, qv0.y * i1_2, dp1_2);
                    di1_0 = fmaf(0.577350269f, qv0.y * p1_0, di1_0);
                    di1_1 = fmaf(0.577350269f, qv0.y * p1_1, di1_1);
                    di1_2 = fmaf(0.577350269f, qv0.y * p1_2, di1_2);
                }
                const float4 qv1 = __ldg(p4 + 1 * SUBWARP);
                { // (0,1)->1 slot 2
                    dp0_0 = fmaf(qv0.z, i1_0, dp0_0);
                    dp0_0 = fmaf(qv0.w, i1_1, dp0_0);
                    dp0_0 = fmaf(qv1.x, i1_2, dp0_0);
                    di1_0 = fmaf(qv0.z, p0_0, di1_0);
                    di1_1 = fmaf(qv0.w, p0_0, di1_1);
                    di1_2 = fmaf(qv1.x, p0_0, di1_2);
                }
                { // (1,0)->1 slot 5
                    dp1_0 = fmaf(qv1.y, i0_0, dp1_0);
                    dp1_1 = fmaf(qv1.z, i0_0, dp1_1);
                    dp1_2 = fmaf(qv1.w, i0_0, dp1_2);
                    di0_0 = fmaf(qv1.y, p1_0, di0_0);
                    di0_0 = fmaf(qv1.z, p1_1, di0_0);
                    di0_0 = fmaf(qv1.w, p1_2, di0_0);
                }
                const float4 qv2 = __ldg(p4 + 2 * SUBWARP);
                { // (2,1)->1 slot 8
                    dp2_0 = fmaf(0.547722558f, qv2.z * i1_0, dp2_0);
                    dp2_0 = fmaf(0.547722558f, qv2.x * i1_2, dp2_0);
                    dp2_1 = fmaf(0.547722558f, qv2.y * i1_0, dp2_1);
                    dp2_1 = fmaf(0.547722558f, qv2.x * i1_1, dp2_1);
                    dp2_2 = fmaf(-0.316227766f, qv2.x * i1_0, dp2_2);
                    dp2_2 = fmaf(0.632455532f, qv2.y * i1_1, dp2_2);
                    dp2_2 = fmaf(-0.316227766f, qv2.z * i1_2, dp2_2);
                    dp2_3 = fmaf(0.547722558f, qv2.z * i1_1, dp2_3);
                    dp2_3 = fmaf(0.547722558f, qv2.y * i1_2, dp2_3);
                    dp2_4 = fmaf(-0.547722558f, qv2.x * i1_0, dp2_4);
                    dp2_4 = fmaf(0.547722558f, qv2.z * i1_2, dp2_4);
                    di1_0 = fmaf(0.547722558f, qv2.z * p2_0, di1_0);
                    di1_0 = fmaf(0.547722558f, qv2.y * p2_1, di1_0);
                    di1_0 = fmaf(-0.316227766f, qv2.x * p2_2, di1_0);
                    di1_0 = fmaf(-0.547722558f, qv2.x * p2_4, di1_0);
                    di1_1 = fmaf(0.547722558f, qv2.x * p2_1, di1_1);
                    di1_1 = fmaf(0.632455532f, qv2.y * p2_2, di1_1);
                    di1_1 = fmaf(0.547722558f, qv2.z * p2_3, di1_1);
                    di1_2 = fmaf(0.547722558f, qv2.x * p2_0, di1_2);
                    di1_2 = fmaf(-0.316227766f, qv2.z * p2_2, di1_2);
                    di1_2 = fmaf(0.547722558f, qv2.y * p2_3, di1_2);
                    di1_2 = fmaf(0.547722558f, qv2.z * p2_4, di1_2);
                }
                const float4 qv3 = __ldg(p4 + 3 * SUBWARP);
                { // (1,1)->2 slot 11
                    dp1_0 = fmaf(-0.40824829f, qv3.y * i1_0, dp1_0);
                    dp1_0 = fmaf(-0.707106781f, qv3.w * i1_0, dp1_0);
                    dp1_0 = fmaf(0.707106781f, qv3.x * i1_1, dp1_0);
                    dp1_0 = fmaf(0.707106781f, qv2.w * i1_2, dp1_0);
                    dp1_1 = fmaf(0.707106781f, qv3.x * i1_0, dp1_1);
                    dp1_1 = fmaf(0.816496581f, qv3.y * i1_1, dp1_1);
                    dp1_1 = fmaf(0.707106781f, qv3.z * i1_2, dp1_1);
                    dp1_2 = fmaf(0.707106781f, qv2.w * i1_0, dp1_2);
                    dp1_2 = fmaf(0.707106781f, qv3.z * i1_1, dp1_2);
                    dp1_2 = fmaf(-0.40824829f, qv3.y * i1_2, dp1_2);
                    dp1_2 = fmaf(0.707106781f, qv3.w * i1_2, dp1_2);
                    di1_0 = fmaf(-0.40824829f, qv3.y * p1_0, di1_0);
                    di1_0 = fmaf(-0.707106781f, qv3.w * p1_0, di1_0);
                    di1_0 = fmaf(0.707106781f, qv3.x * p1_1, di1_0);
                    di1_0 = fmaf(0.707106781f, qv2.w * p1_2, di1_0);
                    di1_1 = fmaf(0.707106781f, qv3.x * p1_0, di1_1);
                    di1_1 = fmaf(0.816496581f, qv3.y * p1_1, di1_1);
                    di1_1 = fmaf(0.707106781f, qv3.z * p1_2, di1_1);
                    di1_2 = fmaf(0.707106781f, qv2.w * p1_0, di1_2);
                    di1_2 = fmaf(0.707106781f, qv3.z * p1_1, di1_2);
                    di1_2 = fmaf(-0.40824829f, qv3.y * p1_2, di1_2);
                    di1_2 = fmaf(0.707106781f, qv3.w * p1_2, di1_2);
                }
                const float4 qv4 = __ldg(p4 + 4 * SUBWARP);
                const float4 qv5 = __ldg(p4 + 5 * SUBWARP);
                { // (2,0)->2 slot 16
                    dp2_0 = fmaf(qv4.x, i0_0, dp2_0);
                    dp2_1 = fmaf(qv4.y, i0_0, dp2_1);
                    dp2_2 = fmaf(qv4.z, i0_0, dp2_2);
                    dp2_3 = fmaf(qv4.w, i0_0, dp2_3);
                    dp2_4 = fmaf(qv5.x, i0_0, dp2_4);
                    di0_0 = fmaf(qv4.x, p2_0, di0_0);
                    di0_0 = fmaf(qv4.y, p2_1, di0_0);
                    di0_0 = fmaf(qv4.z, p2_2, di0_0);
                    di0_0 = fmaf(qv4.w, p2_3, di0_0);
                    di0_0 = fmaf(qv5.x, p2_4, di0_0);
                }

                const float d_r2_0 = dp0_0 * Yk[0];
                const float d_r2_1 = dp1_0 * Yk[1] + dp1_1 * Yk[2] + dp1_2 * Yk[3];
                const float d_r2_2 = dp2_0 * Yk[4] + dp2_1 * Yk[5] + dp2_2 * Yk[6] + dp2_3 * Yk[7] + dp2_4 * Yk[8];
                er_lane = fmaf(d_r2_0, dr2_0, fmaf(d_r2_1, dr2_1, d_r2_2 * dr2_2));
                dY1 = dp1_0 * r2_1; dY2 = dp1_1 * r2_1; dY3 = dp1_2 * r2_1;
                dY4 = dp2_0 * r2_2; dY5 = dp2_1 * r2_2; dY6 = dp2_2 * r2_2; dY7 = dp2_3 * r2_2; dY8 = dp2_4 * r2_2;
                acc_di0   += di0_0;
                acc_di1_0 += di1_0; acc_di1_1 += di1_1; acc_di1_2 += di1_2;
                if constexpr (REM_BF) {
                    acc_df0 = fmaf(-di0_0 * Yk[0], rbf0, acc_df0);
                    er_lane = fmaf(-di0_0 * Yk[0] * f0_j, drbf0, er_lane);
                    const float ydot1 = di1_0 * Yk[1] + di1_1 * Yk[2] + di1_2 * Yk[3];
                    acc_df0 = fmaf(-ydot1, rbf1, acc_df0);
                    er_lane = fmaf(-ydot1 * f0_j, drbf1, er_lane);
                    const float bf1_sc = -f0_j * rbf1;
                    dY1 = fmaf(di1_0, bf1_sc, dY1); dY2 = fmaf(di1_1, bf1_sc, dY2); dY3 = fmaf(di1_2, bf1_sc, dY3);
                }
            }

            // Parallel butterfly sub-warp reduction of 9 scalars (er_lane, dY1..dY8)!
            const bool p0 = (slane & 1) != 0;
            const float u0 = (p0 ? dY1 : er_lane) + __shfl_xor_sync(smask, p0 ? er_lane : dY1, 1);
            const float u1 = (p0 ? dY3 : dY2)     + __shfl_xor_sync(smask, p0 ? dY2 : dY3, 1);
            const float u2 = (p0 ? dY5 : dY4)     + __shfl_xor_sync(smask, p0 ? dY4 : dY5, 1);
            const float u3 = (p0 ? dY7 : dY6)     + __shfl_xor_sync(smask, p0 ? dY6 : dY7, 1);
            const bool p1 = (slane & 2) != 0;
            const float w0 = (p1 ? u1 : u0) + __shfl_xor_sync(smask, p1 ? u0 : u1, 2);
            const float w1 = (p1 ? u3 : u2) + __shfl_xor_sync(smask, p1 ? u2 : u3, 2);
            const bool p2 = (slane & 4) != 0;
            float val = (p2 ? w1 : w0) + __shfl_xor_sync(smask, p2 ? w0 : w1, 4);
            if constexpr (SUBWARP >= 16) val += __shfl_xor_sync(smask, val, 8);
            if constexpr (SUBWARP == 32) val += __shfl_xor_sync(smask, val, 16);
            if (slane < 8) s_er_dY[sid][bi][slane] = val;
            const float dY8_sum = (SUBWARP == 8) ? qwarp_sum_f(dY8, smask) : ((SUBWARP == 16) ? half_warp_sum_f(dY8, smask) : warp_sum_f(dY8));
            if (slane == 0) s_er_dY[sid][bi][8] = dY8_sum;
        }
        __syncwarp(smask);

        FT bfx = (FT)0, bfy = (FT)0, bfz = (FT)0;
        if (slane < bcnt) {
            const float4 vl = s_vl[sid][slane];
            const int i_nb = s_i[sid][slane];
            const float r = fmaxf(vl.w, 1e-8f);
            const float inv_d = 1.0f / r;
            const float ux = vl.x * inv_d, uy = vl.y * inv_d, uz = vl.z * inv_d;
            const float* ed = s_er_dY[sid][slane];
            float gx, gy, gz;
            sh_grad_l2(ux, uy, uz, ed[1], ed[2], ed[3], ed[4], ed[5], ed[6], ed[7], ed[8], gx, gy, gz);
            const float dot = ux * gx + uy * gy + uz * gz;
            bfx = (FT)(ux * ed[0] + (gx - ux * dot) * inv_d);
            bfy = (FT)(uy * ed[0] + (gy - uy * dot) * inv_d);
            bfz = (FT)(uz * ed[0] + (gz - uz * dot) * inv_d);
            if constexpr (F32_F) {
                atomicAdd(forces_f32 + (int64_t)i_nb * 3 + 0, -bfx);
                atomicAdd(forces_f32 + (int64_t)i_nb * 3 + 1, -bfy);
                atomicAdd(forces_f32 + (int64_t)i_nb * 3 + 2, -bfz);
            } else {
                atomicAdd(forces + (int64_t)i_nb * 3 + 0, -bfx);
                atomicAdd(forces + (int64_t)i_nb * 3 + 1, -bfy);
                atomicAdd(forces + (int64_t)i_nb * 3 + 2, -bfz);
            }
            if constexpr (STRESS) {
                v0 += (double)vl.x * (double)bfx;
                v1 += 0.5 * ((double)vl.x * (double)bfy + (double)vl.y * (double)bfx);
                v2 += 0.5 * ((double)vl.x * (double)bfz + (double)vl.z * (double)bfx);
                v3 += (double)vl.y * (double)bfy;
                v4 += 0.5 * ((double)vl.y * (double)bfz + (double)vl.z * (double)bfy);
                v5 += (double)vl.z * (double)bfz;
            }
        }
        if constexpr (F32_F) {
            bfx = (SUBWARP == 8) ? qwarp_sum_f(bfx, smask) : ((SUBWARP == 16) ? half_warp_sum_f(bfx, smask) : warp_sum_f(bfx));
            bfy = (SUBWARP == 8) ? qwarp_sum_f(bfy, smask) : ((SUBWARP == 16) ? half_warp_sum_f(bfy, smask) : warp_sum_f(bfy));
            bfz = (SUBWARP == 8) ? qwarp_sum_f(bfz, smask) : ((SUBWARP == 16) ? half_warp_sum_f(bfz, smask) : warp_sum_f(bfz));
        } else {
            bfx = (SUBWARP == 8) ? qwarp_sum_d(bfx, smask) : ((SUBWARP == 16) ? half_warp_sum_d(bfx, smask) : warp_sum_d(bfx));
            bfy = (SUBWARP == 8) ? qwarp_sum_d(bfy, smask) : ((SUBWARP == 16) ? half_warp_sum_d(bfy, smask) : warp_sum_d(bfy));
            bfz = (SUBWARP == 8) ? qwarp_sum_d(bfz, smask) : ((SUBWARP == 16) ? half_warp_sum_d(bfz, smask) : warp_sum_d(bfz));
        }
        if (slane == 0) { s_sf[sid][0] += bfx; s_sf[sid][1] += bfy; s_sf[sid][2] += bfz; }
        __syncwarp(smask);
    }

    if (active_q) {
        dI_node.p[0][(int64_t)j * n_msg + slane] = acc_di0;
        float* dI1 = dI_node.p[1] + (int64_t)j * 3 * n_msg + slane;
        dI1[0] = acc_di1_0; dI1[n_msg] = acc_di1_1; dI1[2 * n_msg] = acc_di1_2;
    }
    if constexpr (REM_BF) {
        const float df0_tot = (SUBWARP == 8) ? qwarp_sum_f(acc_df0, smask) : ((SUBWARP == 16) ? half_warp_sum_f(acc_df0, smask) : warp_sum_f(acc_df0));
        if (slane == 0) df0_bf[j] = df0_tot;
    }
    if constexpr (STRESS) {
        v0 = (SUBWARP == 8) ? qwarp_sum_d(v0, smask) : ((SUBWARP == 16) ? half_warp_sum_d(v0, smask) : warp_sum_d(v0));
        v1 = (SUBWARP == 8) ? qwarp_sum_d(v1, smask) : ((SUBWARP == 16) ? half_warp_sum_d(v1, smask) : warp_sum_d(v1));
        v2 = (SUBWARP == 8) ? qwarp_sum_d(v2, smask) : ((SUBWARP == 16) ? half_warp_sum_d(v2, smask) : warp_sum_d(v2));
        v3 = (SUBWARP == 8) ? qwarp_sum_d(v3, smask) : ((SUBWARP == 16) ? half_warp_sum_d(v3, smask) : warp_sum_d(v3));
        v4 = (SUBWARP == 8) ? qwarp_sum_d(v4, smask) : ((SUBWARP == 16) ? half_warp_sum_d(v4, smask) : warp_sum_d(v4));
        v5 = (SUBWARP == 8) ? qwarp_sum_d(v5, smask) : ((SUBWARP == 16) ? half_warp_sum_d(v5, smask) : warp_sum_d(v5));
    }
    if (slane == 0) {
        const FT sfx = s_sf[sid][0], sfy = s_sf[sid][1], sfz = s_sf[sid][2];
        if (sfx != (FT)0 || sfy != (FT)0 || sfz != (FT)0) {
            if constexpr (F32_F) {
                atomicAdd(forces_f32 + (int64_t)j * 3 + 0, sfx);
                atomicAdd(forces_f32 + (int64_t)j * 3 + 1, sfy);
                atomicAdd(forces_f32 + (int64_t)j * 3 + 2, sfz);
            } else {
                atomicAdd(forces + (int64_t)j * 3 + 0, sfx);
                atomicAdd(forces + (int64_t)j * 3 + 1, sfy);
                atomicAdd(forces + (int64_t)j * 3 + 2, sfz);
            }
        }
        if constexpr (STRESS) {
            if (v0 != 0.0) atomicAdd(virial + 0, v0); if (v1 != 0.0) atomicAdd(virial + 1, v1);
            if (v2 != 0.0) atomicAdd(virial + 2, v2); if (v3 != 0.0) atomicAdd(virial + 3, v3);
            if (v4 != 0.0) atomicAdd(virial + 4, v4); if (v5 != 0.0) atomicAdd(virial + 5, v5);
        }
    }
}

// Specialized L2 Edge Forward: lfeat2=2, lout2=2, lmsg=2 (N_OUT=35)
template <int SUBWARP, int NB_MAX, bool REM_BF, bool SMEM_C, bool DUAL_G = false>
__global__ void __launch_bounds__(128) ilmlip_l2_edge_fwd_lf2_m2_kernel(
    int N, int S, int n_base2, int n_base1, int n_msg,
    Int4 l2_c, ChebParam r_max2, ChebParam r_max1, float a0_over_sig1, float inv_DA2_sig1_kap_sq,
    const int* __restrict__ row_ptr, const int* __restrict__ row_end, const int* __restrict__ senders,
    const float4* __restrict__ vec_len, const int* __restrict__ species,
    const float* __restrict__ C2, const float* __restrict__ Cbf,
    const float* __restrict__ f0, CPtr4 I_node, Ptr4 A2, float* __restrict__ f1_out) {
    constexpr int NSUB = 128 / SUBWARP;
    constexpr int EBATCH = (SUBWARP == 32) ? 8 : 4;
    constexpr int NB_STRIDE = NB_MAX + 1;
    constexpr int NB1_STRIDE = DUAL_G ? 17 : 1;
    extern __shared__ float smem_c[];
    __shared__ float s_g[NSUB][EBATCH][NB_STRIDE];
    __shared__ float s_g1[DUAL_G ? NSUB : 1][DUAL_G ? EBATCH : 1][NB1_STRIDE];
    __shared__ float s_Y[NSUB][EBATCH][9];
    __shared__ int   s_j[NSUB][EBATCH];
    __shared__ int   s_pair[NSUB][EBATCH];
    __shared__ float s_f0[NSUB][EBATCH];

    const int l2_tot_cols = 3 * n_msg;
    const int bf_tot_cols = 3 * n_msg;
    const int c2_elems = S * S * n_base2 * l2_tot_cols;
    const int cbf_elems = REM_BF ? (S * S * n_base1 * bf_tot_cols) : 0;
    constexpr bool F4_SMEM = SMEM_C && (NB_MAX == 8) && !DUAL_G;
    float4* smem_c4 = reinterpret_cast<float4*>(smem_c);
    float4* smem_bf4 = smem_c4 + (size_t)S * S * 6 * SUBWARP;
    if constexpr (F4_SMEM) {
        const int n_c2_slots = S * S * 3 * SUBWARP;
        for (int idx = threadIdx.x; idx < n_c2_slots; idx += 128) {
            const int q = idx & (SUBWARP - 1);
            const int pl = idx / SUBWARP; const int pair = pl / 3; const int l = pl - pair * 3;
            float4 v0 = make_float4(0.f,0.f,0.f,0.f), v1 = make_float4(0.f,0.f,0.f,0.f);
            if (q < n_msg) {
                const float* src = C2 + (int64_t)pair * 8 * l2_tot_cols + l * n_msg + q;
                v0 = make_float4(__ldg(src), __ldg(src + l2_tot_cols), __ldg(src + 2*l2_tot_cols), __ldg(src + 3*l2_tot_cols));
                v1 = make_float4(__ldg(src + 4*l2_tot_cols), __ldg(src + 5*l2_tot_cols), __ldg(src + 6*l2_tot_cols), __ldg(src + 7*l2_tot_cols));
            }
            smem_c4[(pair * 6 + l * 2 + 0) * SUBWARP + q] = v0;
            smem_c4[(pair * 6 + l * 2 + 1) * SUBWARP + q] = v1;
        }
        if constexpr (REM_BF) {
            const int n_bf_slots = S * S * 3 * SUBWARP;
            for (int idx = threadIdx.x; idx < n_bf_slots; idx += 128) {
                const int q = idx & (SUBWARP - 1);
                const int pl = idx / SUBWARP; const int pair = pl / 3; const int l = pl - pair * 3;
                float4 v0 = make_float4(0.f,0.f,0.f,0.f), v1 = make_float4(0.f,0.f,0.f,0.f);
                if (q < n_msg) {
                    const float* src = Cbf + (int64_t)pair * 8 * bf_tot_cols + l * n_msg + q;
                    v0 = make_float4(__ldg(src), __ldg(src + bf_tot_cols), __ldg(src + 2*bf_tot_cols), __ldg(src + 3*bf_tot_cols));
                    v1 = make_float4(__ldg(src + 4*bf_tot_cols), __ldg(src + 5*bf_tot_cols), __ldg(src + 6*bf_tot_cols), __ldg(src + 7*bf_tot_cols));
                }
                smem_bf4[(pair * 6 + l * 2 + 0) * SUBWARP + q] = v0;
                smem_bf4[(pair * 6 + l * 2 + 1) * SUBWARP + q] = v1;
            }
        }
        __syncthreads();
    } else if constexpr (SMEM_C) {
        for (int idx = threadIdx.x; idx < c2_elems; idx += 128) smem_c[idx] = __ldg(C2 + idx);
        if constexpr (REM_BF) {
            float* smem_bf = smem_c + c2_elems;
            for (int idx = threadIdx.x; idx < cbf_elems; idx += 128) smem_bf[idx] = __ldg(Cbf + idx);
        }
        __syncthreads();
    }
    const int sid = threadIdx.x / SUBWARP;
    const int slane = threadIdx.x & (SUBWARP - 1);
    const unsigned smask = (SUBWARP == 8) ? (0xffu << ((sid & 3) * 8)) : ((SUBWARP == 16) ? ((sid & 1) ? 0xffff0000u : 0x0000ffffu) : 0xffffffffu);
    const int i = blockIdx.x * NSUB + sid;
    if (i >= N) return;
    const int z_i = species[i];
    const int eb = row_ptr[i], ee = row_end[i];
    const bool active_q = (slane < n_msg);
    const float* C2_base = SMEM_C ? smem_c : C2;
    const float* Cbf_base = REM_BF ? (SMEM_C ? (smem_c + c2_elems) : Cbf) : nullptr;

    float acc[35];
    #pragma unroll
    for (int k = 0; k < 35; ++k) acc[k] = 0.0f;

    for (int eb_b = eb; eb_b < ee; eb_b += EBATCH) {
        const int bcnt = (ee - eb_b < EBATCH) ? (ee - eb_b) : EBATCH;
        if (slane < bcnt) {
            const int e = eb_b + slane;
            const float4 vl = __ldg(vec_len + e);
            const int j = __ldg(senders + e);
            const float r = fmaxf(vl.w, 1e-8f);
            s_j[sid][slane] = j;
            s_pair[sid][slane] = z_i * S + __ldg(species + j);
            if constexpr (REM_BF) s_f0[sid][slane] = __ldg(f0 + j);
            if constexpr (NB_MAX == 8) {
                float4 g03, g47, d0, d1;
                eval_cheb8_f4<false>(r, r_max2, g03, g47, d0, d1);
                float* dst = s_g[sid][slane];
                dst[0]=g03.x; dst[1]=g03.y; dst[2]=g03.z; dst[3]=g03.w;
                dst[4]=g47.x; dst[5]=g47.y; dst[6]=g47.z; dst[7]=g47.w;
            } else {
                eval_cheb<false>(r, r_max2, n_base2, s_g[sid][slane], nullptr);
            }
            if constexpr (DUAL_G && REM_BF && SUBWARP == 8) {
                eval_cheb<false>(r, r_max1, n_base1, s_g1[sid][slane], nullptr);
            }
        } else if (slane >= EBATCH && slane < EBATCH + bcnt) {
            const int bi = slane - EBATCH;
            const float4 vl = __ldg(vec_len + eb_b + bi);
            const float r = fmaxf(vl.w, 1e-8f);
            edge_sh9(vl.x, vl.y, vl.z, r, s_Y[sid][bi]);
        } else if constexpr (DUAL_G && REM_BF && SUBWARP >= 16) {
            if (slane >= 2 * EBATCH && slane < 2 * EBATCH + bcnt) {
                const int bi = slane - 2 * EBATCH;
                const float4 vl = __ldg(vec_len + eb_b + bi);
                const float r = fmaxf(vl.w, 1e-8f);
                eval_cheb<false>(r, r_max1, n_base1, s_g1[sid][bi], nullptr);
            }
        }
        __syncwarp(smask);

        if (active_q) {
            for (int bi = 0; bi < bcnt; ++bi) {
                const int j = s_j[sid][bi];
                const int pair = s_pair[sid][bi];
                const float* gk = s_g[sid][bi];
                const float* Yk = s_Y[sid][bi];
                const float* C2p = C2_base + (int64_t)pair * n_base2 * l2_tot_cols + slane;
                float r2_0 = 0.0f, r2_1 = 0.0f, r2_2 = 0.0f;
                if constexpr (F4_SMEM) {
                    const float4 g03 = make_float4(gk[0], gk[1], gk[2], gk[3]);
                    const float4 g47 = make_float4(gk[4], gk[5], gk[6], gk[7]);
                    const float4* cp4 = smem_c4 + pair * 6 * SUBWARP + slane;
                    r2_0 = v1_dot4(cp4[0 * SUBWARP], g03) + v1_dot4(cp4[1 * SUBWARP], g47);
                    r2_1 = v1_dot4(cp4[2 * SUBWARP], g03) + v1_dot4(cp4[3 * SUBWARP], g47);
                    r2_2 = v1_dot4(cp4[4 * SUBWARP], g03) + v1_dot4(cp4[5 * SUBWARP], g47);
                } else {
                    auto acc_c2 = [&](int k) {
                        const float gv = gk[k]; const float* rrow = C2p + k * l2_tot_cols;
                        r2_0 = fmaf(SMEM_C ? rrow[0]         : __ldg(rrow),           gv, r2_0);
                        r2_1 = fmaf(SMEM_C ? rrow[n_msg]     : __ldg(rrow + n_msg),   gv, r2_1);
                        r2_2 = fmaf(SMEM_C ? rrow[2 * n_msg] : __ldg(rrow + 2*n_msg), gv, r2_2);
                    };
                    if constexpr (NB_MAX == 8) {
                        #pragma unroll
                        for (int k = 0; k < 8; ++k) acc_c2(k);
                    } else {
                        if (n_base2 == 12)      {
                            #pragma unroll 4
                            for (int k = 0; k < 12; ++k) acc_c2(k); }
                        else if (n_base2 == 14) {
                            #pragma unroll 4
                            for (int k = 0; k < 14; ++k) acc_c2(k); }
                        else if (n_base2 == 16) {
                            #pragma unroll 4
                            for (int k = 0; k < 16; ++k) acc_c2(k); }
                        else { for (int k = 0; k < n_base2; ++k) acc_c2(k); }
                    }
                }

                float rbf0 = 0.0f, rbf1 = 0.0f, rbf2 = 0.0f;
                if constexpr (REM_BF) {
                    const float f0_j = s_f0[sid][bi];
                    if constexpr (F4_SMEM) {
                        const float4 g03 = make_float4(gk[0], gk[1], gk[2], gk[3]);
                        const float4 g47 = make_float4(gk[4], gk[5], gk[6], gk[7]);
                        const float4* bp4 = smem_bf4 + pair * 6 * SUBWARP + slane;
                        rbf0 = v1_dot4(bp4[0 * SUBWARP], g03) + v1_dot4(bp4[1 * SUBWARP], g47);
                        rbf1 = v1_dot4(bp4[2 * SUBWARP], g03) + v1_dot4(bp4[3 * SUBWARP], g47);
                        rbf2 = v1_dot4(bp4[4 * SUBWARP], g03) + v1_dot4(bp4[5 * SUBWARP], g47);
                    } else {
                        const float* gkb = DUAL_G ? s_g1[sid][bi] : gk;
                        const float* Cbp = Cbf_base + (int64_t)pair * n_base1 * bf_tot_cols + slane;
                        auto acc_bf = [&](int k) {
                            const float gv = gkb[k]; const float* rrow = Cbp + k * bf_tot_cols;
                            rbf0 = fmaf(SMEM_C ? rrow[0]     : __ldg(rrow),         gv, rbf0);
                            rbf1 = fmaf(SMEM_C ? rrow[n_msg] : __ldg(rrow + n_msg), gv, rbf1);
                            rbf2 = fmaf(SMEM_C ? rrow[2*n_msg] : __ldg(rrow + 2*n_msg), gv, rbf2);
                        };
                        if constexpr (!DUAL_G && NB_MAX == 8) {
                            #pragma unroll
                            for (int k = 0; k < 8; ++k) acc_bf(k);
                        } else {
                            if (n_base1 == 8)       {
                                #pragma unroll
                                for (int k = 0; k < 8; ++k) acc_bf(k); }
                            else if (n_base1 == 12) {
                                #pragma unroll 4
                                for (int k = 0; k < 12; ++k) acc_bf(k); }
                            else if (n_base1 == 14) {
                                #pragma unroll 4
                                for (int k = 0; k < 14; ++k) acc_bf(k); }
                            else if (n_base1 == 16) {
                                #pragma unroll 4
                                for (int k = 0; k < 16; ++k) acc_bf(k); }
                            else { for (int k = 0; k < n_base1; ++k) acc_bf(k); }
                        }
                    }
                    rbf0 *= f0_j; rbf1 *= f0_j; rbf2 *= f0_j;
                }
                const float i0_0 = __ldg(I_node.p[0] + (int64_t)j * n_msg + slane) - (REM_BF ? rbf0 * Yk[0] : 0.0f);
                const float* pI1 = I_node.p[1] + (int64_t)j * 3 * n_msg + slane;
                const float i1_0 = __ldg(pI1)           - (REM_BF ? rbf1 * Yk[1] : 0.0f);
                const float i1_1 = __ldg(pI1 + n_msg)   - (REM_BF ? rbf1 * Yk[2] : 0.0f);
                const float i1_2 = __ldg(pI1 + 2*n_msg) - (REM_BF ? rbf1 * Yk[3] : 0.0f);
                const float* pI2 = I_node.p[2] + (int64_t)j * 5 * n_msg + slane;
                const float i2_0 = __ldg(pI2)           - (REM_BF ? rbf2 * Yk[4] : 0.0f);
                const float i2_1 = __ldg(pI2 + n_msg)   - (REM_BF ? rbf2 * Yk[5] : 0.0f);
                const float i2_2 = __ldg(pI2 + 2*n_msg) - (REM_BF ? rbf2 * Yk[6] : 0.0f);
                const float i2_3 = __ldg(pI2 + 3*n_msg) - (REM_BF ? rbf2 * Yk[7] : 0.0f);
                const float i2_4 = __ldg(pI2 + 4*n_msg) - (REM_BF ? rbf2 * Yk[8] : 0.0f);
                const float p0_0 = r2_0 * Yk[0];
                const float p1_0 = r2_1 * Yk[1], p1_1 = r2_1 * Yk[2], p1_2 = r2_1 * Yk[3];
                const float p2_0 = r2_2 * Yk[4], p2_1 = r2_2 * Yk[5], p2_2 = r2_2 * Yk[6], p2_3 = r2_2 * Yk[7], p2_4 = r2_2 * Yk[8];
                acc[0] = fmaf(p0_0, i0_0, acc[0]);
                acc[1] = fmaf(0.577350269f, p1_0 * i1_0, acc[1]);
                acc[1] = fmaf(0.577350269f, p1_1 * i1_1, acc[1]);
                acc[1] = fmaf(0.577350269f, p1_2 * i1_2, acc[1]);
                acc[2] = fmaf(0.447213595f, p2_0 * i2_0, acc[2]);
                acc[2] = fmaf(0.447213595f, p2_1 * i2_1, acc[2]);
                acc[2] = fmaf(0.447213595f, p2_2 * i2_2, acc[2]);
                acc[2] = fmaf(0.447213595f, p2_3 * i2_3, acc[2]);
                acc[2] = fmaf(0.447213595f, p2_4 * i2_4, acc[2]);
                acc[3] = fmaf(p0_0, i1_0, acc[3]);
                acc[4] = fmaf(p0_0, i1_1, acc[4]);
                acc[5] = fmaf(p0_0, i1_2, acc[5]);
                acc[6] = fmaf(p1_0, i0_0, acc[6]);
                acc[7] = fmaf(p1_1, i0_0, acc[7]);
                acc[8] = fmaf(p1_2, i0_0, acc[8]);
                acc[9] = fmaf(-0.316227766f, p1_0 * i2_2, acc[9]);
                acc[9] = fmaf(-0.547722558f, p1_0 * i2_4, acc[9]);
                acc[9] = fmaf(0.547722558f, p1_1 * i2_1, acc[9]);
                acc[9] = fmaf(0.547722558f, p1_2 * i2_0, acc[9]);
                acc[10] = fmaf(0.547722558f, p1_0 * i2_1, acc[10]);
                acc[10] = fmaf(0.632455532f, p1_1 * i2_2, acc[10]);
                acc[10] = fmaf(0.547722558f, p1_2 * i2_3, acc[10]);
                acc[11] = fmaf(0.547722558f, p1_0 * i2_0, acc[11]);
                acc[11] = fmaf(0.547722558f, p1_1 * i2_3, acc[11]);
                acc[11] = fmaf(-0.316227766f, p1_2 * i2_2, acc[11]);
                acc[11] = fmaf(0.547722558f, p1_2 * i2_4, acc[11]);
                acc[12] = fmaf(0.547722558f, p2_0 * i1_2, acc[12]);
                acc[12] = fmaf(0.547722558f, p2_1 * i1_1, acc[12]);
                acc[12] = fmaf(-0.316227766f, p2_2 * i1_0, acc[12]);
                acc[12] = fmaf(-0.547722558f, p2_4 * i1_0, acc[12]);
                acc[13] = fmaf(0.547722558f, p2_1 * i1_0, acc[13]);
                acc[13] = fmaf(0.632455532f, p2_2 * i1_1, acc[13]);
                acc[13] = fmaf(0.547722558f, p2_3 * i1_2, acc[13]);
                acc[14] = fmaf(0.547722558f, p2_0 * i1_0, acc[14]);
                acc[14] = fmaf(-0.316227766f, p2_2 * i1_2, acc[14]);
                acc[14] = fmaf(0.547722558f, p2_3 * i1_1, acc[14]);
                acc[14] = fmaf(0.547722558f, p2_4 * i1_2, acc[14]);
                acc[15] = fmaf(p0_0, i2_0, acc[15]);
                acc[16] = fmaf(p0_0, i2_1, acc[16]);
                acc[17] = fmaf(p0_0, i2_2, acc[17]);
                acc[18] = fmaf(p0_0, i2_3, acc[18]);
                acc[19] = fmaf(p0_0, i2_4, acc[19]);
                acc[20] = fmaf(0.707106781f, p1_0 * i1_2, acc[20]);
                acc[20] = fmaf(0.707106781f, p1_2 * i1_0, acc[20]);
                acc[21] = fmaf(0.707106781f, p1_0 * i1_1, acc[21]);
                acc[21] = fmaf(0.707106781f, p1_1 * i1_0, acc[21]);
                acc[22] = fmaf(-0.40824829f, p1_0 * i1_0, acc[22]);
                acc[22] = fmaf(0.816496581f, p1_1 * i1_1, acc[22]);
                acc[22] = fmaf(-0.40824829f, p1_2 * i1_2, acc[22]);
                acc[23] = fmaf(0.707106781f, p1_1 * i1_2, acc[23]);
                acc[23] = fmaf(0.707106781f, p1_2 * i1_1, acc[23]);
                acc[24] = fmaf(-0.707106781f, p1_0 * i1_0, acc[24]);
                acc[24] = fmaf(0.707106781f, p1_2 * i1_2, acc[24]);
                acc[25] = fmaf(p2_0, i0_0, acc[25]);
                acc[26] = fmaf(p2_1, i0_0, acc[26]);
                acc[27] = fmaf(p2_2, i0_0, acc[27]);
                acc[28] = fmaf(p2_3, i0_0, acc[28]);
                acc[29] = fmaf(p2_4, i0_0, acc[29]);
                acc[30] = fmaf(-0.534522484f, p2_0 * i2_2, acc[30]);
                acc[30] = fmaf(0.46291005f, p2_1 * i2_3, acc[30]);
                acc[30] = fmaf(-0.534522484f, p2_2 * i2_0, acc[30]);
                acc[30] = fmaf(0.46291005f, p2_3 * i2_1, acc[30]);
                acc[31] = fmaf(0.46291005f, p2_0 * i2_3, acc[31]);
                acc[31] = fmaf(0.267261242f, p2_1 * i2_2, acc[31]);
                acc[31] = fmaf(-0.46291005f, p2_1 * i2_4, acc[31]);
                acc[31] = fmaf(0.267261242f, p2_2 * i2_1, acc[31]);
                acc[31] = fmaf(0.46291005f, p2_3 * i2_0, acc[31]);
                acc[31] = fmaf(-0.46291005f, p2_4 * i2_1, acc[31]);
                acc[32] = fmaf(-0.534522484f, p2_0 * i2_0, acc[32]);
                acc[32] = fmaf(0.267261242f, p2_1 * i2_1, acc[32]);
                acc[32] = fmaf(0.534522484f, p2_2 * i2_2, acc[32]);
                acc[32] = fmaf(0.267261242f, p2_3 * i2_3, acc[32]);
                acc[32] = fmaf(-0.534522484f, p2_4 * i2_4, acc[32]);
                acc[33] = fmaf(0.46291005f, p2_0 * i2_1, acc[33]);
                acc[33] = fmaf(0.46291005f, p2_1 * i2_0, acc[33]);
                acc[33] = fmaf(0.267261242f, p2_2 * i2_3, acc[33]);
                acc[33] = fmaf(0.267261242f, p2_3 * i2_2, acc[33]);
                acc[33] = fmaf(0.46291005f, p2_3 * i2_4, acc[33]);
                acc[33] = fmaf(0.46291005f, p2_4 * i2_3, acc[33]);
                acc[34] = fmaf(-0.46291005f, p2_1 * i2_1, acc[34]);
                acc[34] = fmaf(-0.534522484f, p2_2 * i2_4, acc[34]);
                acc[34] = fmaf(0.46291005f, p2_3 * i2_3, acc[34]);
                acc[34] = fmaf(-0.534522484f, p2_4 * i2_2, acc[34]);
            }
        }
        __syncwarp(smask);
    }

    float sq_lane = 0.0f;
    if (active_q) {
        #pragma unroll
        for (int k = 0; k < 35; ++k) sq_lane = fmaf(acc[k], acc[k], sq_lane); }
    const float sq_tot = (SUBWARP == 8) ? qwarp_sum_f(sq_lane, smask) : ((SUBWARP == 16) ? half_warp_sum_f(sq_lane, smask) : warp_sum_f(sq_lane));
    const float f1 = a0_over_sig1 / sqrtf(1.0f + sq_tot * inv_DA2_sig1_kap_sq);
    if (slane == 0) f1_out[i] = f1;
    if (active_q) {
        const int c0 = l2_c.v[0], c1 = l2_c.v[1], c2 = l2_c.v[2];
        float* d0 = A2.p[0] + (int64_t)i * c0 + slane;
        float* d1 = A2.p[1] + (int64_t)i * 3 * c1 + slane;
        float* d2 = A2.p[2] + (int64_t)i * 5 * c2 + slane;
        d0[0 * n_msg] = acc[0] * f1;
        d0[1 * n_msg] = acc[1] * f1;
        d0[2 * n_msg] = acc[2] * f1;
        d1[0 * c1 + 0 * n_msg] = acc[3] * f1;
        d1[1 * c1 + 0 * n_msg] = acc[4] * f1;
        d1[2 * c1 + 0 * n_msg] = acc[5] * f1;
        d1[0 * c1 + 1 * n_msg] = acc[6] * f1;
        d1[1 * c1 + 1 * n_msg] = acc[7] * f1;
        d1[2 * c1 + 1 * n_msg] = acc[8] * f1;
        d1[0 * c1 + 2 * n_msg] = acc[9] * f1;
        d1[1 * c1 + 2 * n_msg] = acc[10] * f1;
        d1[2 * c1 + 2 * n_msg] = acc[11] * f1;
        d1[0 * c1 + 3 * n_msg] = acc[12] * f1;
        d1[1 * c1 + 3 * n_msg] = acc[13] * f1;
        d1[2 * c1 + 3 * n_msg] = acc[14] * f1;
        d2[0 * c2 + 0 * n_msg] = acc[15] * f1;
        d2[1 * c2 + 0 * n_msg] = acc[16] * f1;
        d2[2 * c2 + 0 * n_msg] = acc[17] * f1;
        d2[3 * c2 + 0 * n_msg] = acc[18] * f1;
        d2[4 * c2 + 0 * n_msg] = acc[19] * f1;
        d2[0 * c2 + 1 * n_msg] = acc[20] * f1;
        d2[1 * c2 + 1 * n_msg] = acc[21] * f1;
        d2[2 * c2 + 1 * n_msg] = acc[22] * f1;
        d2[3 * c2 + 1 * n_msg] = acc[23] * f1;
        d2[4 * c2 + 1 * n_msg] = acc[24] * f1;
        d2[0 * c2 + 2 * n_msg] = acc[25] * f1;
        d2[1 * c2 + 2 * n_msg] = acc[26] * f1;
        d2[2 * c2 + 2 * n_msg] = acc[27] * f1;
        d2[3 * c2 + 2 * n_msg] = acc[28] * f1;
        d2[4 * c2 + 2 * n_msg] = acc[29] * f1;
        d2[0 * c2 + 3 * n_msg] = acc[30] * f1;
        d2[1 * c2 + 3 * n_msg] = acc[31] * f1;
        d2[2 * c2 + 3 * n_msg] = acc[32] * f1;
        d2[3 * c2 + 3 * n_msg] = acc[33] * f1;
        d2[4 * c2 + 3 * n_msg] = acc[34] * f1;
    }
}

template <int SUBWARP>
__global__ void __launch_bounds__(128) ilmlip_gate_bwd_pack_l2_lf2_m2_kernel(
    int N, int n_msg, Int4 l2_c, float inv_DA2_a0_kap_sq,
    CPtr4 A2, CPtr4 dA2, const float* __restrict__ f1_arr, float* __restrict__ dA2_pack) {
    constexpr int NSUB = 128 / SUBWARP;
    const int sid = threadIdx.x / SUBWARP;
    const int slane = threadIdx.x & (SUBWARP - 1);
    const unsigned smask = (SUBWARP == 8) ? (0xffu << ((sid & 3) * 8)) : ((SUBWARP == 16) ? ((sid & 1) ? 0xffff0000u : 0x0000ffffu) : 0xffffffffu);
    const int i = blockIdx.x * NSUB + sid;
    if (i >= N) return;
    const bool active_q = (slane < n_msg);
    float av[36], dv[36];
    av[35] = 0.0f; dv[35] = 0.0f;
    float dot_lane = 0.0f;
    if (active_q) {
        const int c0 = l2_c.v[0], c1 = l2_c.v[1], c2 = l2_c.v[2];
        const float* pA0 = A2.p[0] + (int64_t)i * c0 + slane; const float* pdA0 = dA2.p[0] + (int64_t)i * c0 + slane;
        const float* pA1 = A2.p[1] + (int64_t)i * 3 * c1 + slane; const float* pdA1 = dA2.p[1] + (int64_t)i * 3 * c1 + slane;
        const float* pA2 = A2.p[2] + (int64_t)i * 5 * c2 + slane; const float* pdA2 = dA2.p[2] + (int64_t)i * 5 * c2 + slane;
        av[0] = pA0[0 * n_msg]; dv[0] = pdA0[0 * n_msg];
        av[1] = pA0[1 * n_msg]; dv[1] = pdA0[1 * n_msg];
        av[2] = pA0[2 * n_msg]; dv[2] = pdA0[2 * n_msg];
        av[3] = pA1[0 * c1 + 0 * n_msg]; dv[3] = pdA1[0 * c1 + 0 * n_msg];
        av[4] = pA1[1 * c1 + 0 * n_msg]; dv[4] = pdA1[1 * c1 + 0 * n_msg];
        av[5] = pA1[2 * c1 + 0 * n_msg]; dv[5] = pdA1[2 * c1 + 0 * n_msg];
        av[6] = pA1[0 * c1 + 1 * n_msg]; dv[6] = pdA1[0 * c1 + 1 * n_msg];
        av[7] = pA1[1 * c1 + 1 * n_msg]; dv[7] = pdA1[1 * c1 + 1 * n_msg];
        av[8] = pA1[2 * c1 + 1 * n_msg]; dv[8] = pdA1[2 * c1 + 1 * n_msg];
        av[9] = pA1[0 * c1 + 2 * n_msg]; dv[9] = pdA1[0 * c1 + 2 * n_msg];
        av[10] = pA1[1 * c1 + 2 * n_msg]; dv[10] = pdA1[1 * c1 + 2 * n_msg];
        av[11] = pA1[2 * c1 + 2 * n_msg]; dv[11] = pdA1[2 * c1 + 2 * n_msg];
        av[12] = pA1[0 * c1 + 3 * n_msg]; dv[12] = pdA1[0 * c1 + 3 * n_msg];
        av[13] = pA1[1 * c1 + 3 * n_msg]; dv[13] = pdA1[1 * c1 + 3 * n_msg];
        av[14] = pA1[2 * c1 + 3 * n_msg]; dv[14] = pdA1[2 * c1 + 3 * n_msg];
        av[15] = pA2[0 * c2 + 0 * n_msg]; dv[15] = pdA2[0 * c2 + 0 * n_msg];
        av[16] = pA2[1 * c2 + 0 * n_msg]; dv[16] = pdA2[1 * c2 + 0 * n_msg];
        av[17] = pA2[2 * c2 + 0 * n_msg]; dv[17] = pdA2[2 * c2 + 0 * n_msg];
        av[18] = pA2[3 * c2 + 0 * n_msg]; dv[18] = pdA2[3 * c2 + 0 * n_msg];
        av[19] = pA2[4 * c2 + 0 * n_msg]; dv[19] = pdA2[4 * c2 + 0 * n_msg];
        av[20] = pA2[0 * c2 + 1 * n_msg]; dv[20] = pdA2[0 * c2 + 1 * n_msg];
        av[21] = pA2[1 * c2 + 1 * n_msg]; dv[21] = pdA2[1 * c2 + 1 * n_msg];
        av[22] = pA2[2 * c2 + 1 * n_msg]; dv[22] = pdA2[2 * c2 + 1 * n_msg];
        av[23] = pA2[3 * c2 + 1 * n_msg]; dv[23] = pdA2[3 * c2 + 1 * n_msg];
        av[24] = pA2[4 * c2 + 1 * n_msg]; dv[24] = pdA2[4 * c2 + 1 * n_msg];
        av[25] = pA2[0 * c2 + 2 * n_msg]; dv[25] = pdA2[0 * c2 + 2 * n_msg];
        av[26] = pA2[1 * c2 + 2 * n_msg]; dv[26] = pdA2[1 * c2 + 2 * n_msg];
        av[27] = pA2[2 * c2 + 2 * n_msg]; dv[27] = pdA2[2 * c2 + 2 * n_msg];
        av[28] = pA2[3 * c2 + 2 * n_msg]; dv[28] = pdA2[3 * c2 + 2 * n_msg];
        av[29] = pA2[4 * c2 + 2 * n_msg]; dv[29] = pdA2[4 * c2 + 2 * n_msg];
        av[30] = pA2[0 * c2 + 3 * n_msg]; dv[30] = pdA2[0 * c2 + 3 * n_msg];
        av[31] = pA2[1 * c2 + 3 * n_msg]; dv[31] = pdA2[1 * c2 + 3 * n_msg];
        av[32] = pA2[2 * c2 + 3 * n_msg]; dv[32] = pdA2[2 * c2 + 3 * n_msg];
        av[33] = pA2[3 * c2 + 3 * n_msg]; dv[33] = pdA2[3 * c2 + 3 * n_msg];
        av[34] = pA2[4 * c2 + 3 * n_msg]; dv[34] = pdA2[4 * c2 + 3 * n_msg];
        #pragma unroll
        for (int k = 0; k < 35; ++k) dot_lane = fmaf(av[k], dv[k], dot_lane);
    }
    const float dot = (SUBWARP == 8) ? qwarp_sum_f(dot_lane, smask) : ((SUBWARP == 16) ? half_warp_sum_f(dot_lane, smask) : warp_sum_f(dot_lane));
    const float f1 = f1_arr[i];
    const float sc = (dot * f1) * inv_DA2_a0_kap_sq;
    if (active_q) {
        float4* dst4 = reinterpret_cast<float4*>(dA2_pack) + (int64_t)i * (9 * SUBWARP) + slane;
        dst4[0 * SUBWARP] = make_float4(fmaf(f1, dv[0], -sc * av[0]), fmaf(f1, dv[1], -sc * av[1]), fmaf(f1, dv[2], -sc * av[2]), fmaf(f1, dv[3], -sc * av[3]));
        dst4[1 * SUBWARP] = make_float4(fmaf(f1, dv[4], -sc * av[4]), fmaf(f1, dv[5], -sc * av[5]), fmaf(f1, dv[6], -sc * av[6]), fmaf(f1, dv[7], -sc * av[7]));
        dst4[2 * SUBWARP] = make_float4(fmaf(f1, dv[8], -sc * av[8]), fmaf(f1, dv[9], -sc * av[9]), fmaf(f1, dv[10], -sc * av[10]), fmaf(f1, dv[11], -sc * av[11]));
        dst4[3 * SUBWARP] = make_float4(fmaf(f1, dv[12], -sc * av[12]), fmaf(f1, dv[13], -sc * av[13]), fmaf(f1, dv[14], -sc * av[14]), fmaf(f1, dv[15], -sc * av[15]));
        dst4[4 * SUBWARP] = make_float4(fmaf(f1, dv[16], -sc * av[16]), fmaf(f1, dv[17], -sc * av[17]), fmaf(f1, dv[18], -sc * av[18]), fmaf(f1, dv[19], -sc * av[19]));
        dst4[5 * SUBWARP] = make_float4(fmaf(f1, dv[20], -sc * av[20]), fmaf(f1, dv[21], -sc * av[21]), fmaf(f1, dv[22], -sc * av[22]), fmaf(f1, dv[23], -sc * av[23]));
        dst4[6 * SUBWARP] = make_float4(fmaf(f1, dv[24], -sc * av[24]), fmaf(f1, dv[25], -sc * av[25]), fmaf(f1, dv[26], -sc * av[26]), fmaf(f1, dv[27], -sc * av[27]));
        dst4[7 * SUBWARP] = make_float4(fmaf(f1, dv[28], -sc * av[28]), fmaf(f1, dv[29], -sc * av[29]), fmaf(f1, dv[30], -sc * av[30]), fmaf(f1, dv[31], -sc * av[31]));
        dst4[8 * SUBWARP] = make_float4(fmaf(f1, dv[32], -sc * av[32]), fmaf(f1, dv[33], -sc * av[33]), fmaf(f1, dv[34], -sc * av[34]), 0.0f);
    }
}

// Specialized SENDER-OWNED ZERO-ATOMIC L2 Edge Backward: lfeat2=2, lout2=2, lmsg=2 (N_OUT=35, N_VEC4=9)
template <int SUBWARP, int NB_MAX, bool REM_BF, bool STRESS, bool F32_F, bool SMEM_C, bool DUAL_G = false>
__global__ void __launch_bounds__(128, 4) ilmlip_l2_edge_bwd_lf2_m2_sender_kernel(
    int N, int S, int n_base2, int n_base1, int n_msg, ChebParam r_max2, ChebParam r_max1,
    const int* __restrict__ row_ptr, const int* __restrict__ row_end, const int* __restrict__ senders,
    const float4* __restrict__ vec_len, const int* __restrict__ species,
    const float* __restrict__ C2, const float* __restrict__ Cbf,
    const float* __restrict__ f0, CPtr4 I_node, const float* __restrict__ dA2_pack,
    Ptr4 dI_node, float* __restrict__ df0_bf,
    double* __restrict__ forces, float* __restrict__ forces_f32, double* __restrict__ virial) {
    using FT = typename std::conditional<F32_F, float, double>::type;
    constexpr int NSUB = 128 / SUBWARP;
    constexpr int EBATCH = (SUBWARP == 32) ? 8 : 4;
    constexpr int NB_STRIDE = NB_MAX + 1;
    constexpr int NB1_STRIDE = DUAL_G ? 17 : 1;
    extern __shared__ float smem_c[];
    __shared__ float  s_g[NSUB][EBATCH][NB_STRIDE];
    __shared__ float  s_dg[NSUB][EBATCH][NB_STRIDE];
    __shared__ float  s_g1[DUAL_G ? NSUB : 1][DUAL_G ? EBATCH : 1][NB1_STRIDE];
    __shared__ float  s_dg1[DUAL_G ? NSUB : 1][DUAL_G ? EBATCH : 1][NB1_STRIDE];
    __shared__ float  s_Y[NSUB][EBATCH][9];
    __shared__ float4 s_vl[NSUB][EBATCH];
    __shared__ int    s_i[NSUB][EBATCH];
    __shared__ int    s_pair[NSUB][EBATCH];
    __shared__ float  s_er_dY[NSUB][EBATCH][9];
    __shared__ FT     s_sf[NSUB][3];

    const int l2_tot_cols = 3 * n_msg;
    const int bf_tot_cols = 3 * n_msg;
    const int c2_elems = S * S * n_base2 * l2_tot_cols;
    const int cbf_elems = REM_BF ? (S * S * n_base1 * bf_tot_cols) : 0;
    constexpr bool F4_SMEM = SMEM_C && (NB_MAX == 8) && !DUAL_G;
    float4* smem_c4 = reinterpret_cast<float4*>(smem_c);
    float4* smem_bf4 = smem_c4 + (size_t)S * S * 6 * SUBWARP;
    if constexpr (F4_SMEM) {
        const int n_c2_slots = S * S * 3 * SUBWARP;
        for (int idx = threadIdx.x; idx < n_c2_slots; idx += 128) {
            const int q = idx & (SUBWARP - 1);
            const int pl = idx / SUBWARP; const int pair = pl / 3; const int l = pl - pair * 3;
            float4 v0 = make_float4(0.f,0.f,0.f,0.f), v1 = make_float4(0.f,0.f,0.f,0.f);
            if (q < n_msg) {
                const float* src = C2 + (int64_t)pair * 8 * l2_tot_cols + l * n_msg + q;
                v0 = make_float4(__ldg(src), __ldg(src + l2_tot_cols), __ldg(src + 2*l2_tot_cols), __ldg(src + 3*l2_tot_cols));
                v1 = make_float4(__ldg(src + 4*l2_tot_cols), __ldg(src + 5*l2_tot_cols), __ldg(src + 6*l2_tot_cols), __ldg(src + 7*l2_tot_cols));
            }
            smem_c4[(pair * 6 + l * 2 + 0) * SUBWARP + q] = v0;
            smem_c4[(pair * 6 + l * 2 + 1) * SUBWARP + q] = v1;
        }
        if constexpr (REM_BF) {
            const int n_bf_slots = S * S * 3 * SUBWARP;
            for (int idx = threadIdx.x; idx < n_bf_slots; idx += 128) {
                const int q = idx & (SUBWARP - 1);
                const int pl = idx / SUBWARP; const int pair = pl / 3; const int l = pl - pair * 3;
                float4 v0 = make_float4(0.f,0.f,0.f,0.f), v1 = make_float4(0.f,0.f,0.f,0.f);
                if (q < n_msg) {
                    const float* src = Cbf + (int64_t)pair * 8 * bf_tot_cols + l * n_msg + q;
                    v0 = make_float4(__ldg(src), __ldg(src + bf_tot_cols), __ldg(src + 2*bf_tot_cols), __ldg(src + 3*bf_tot_cols));
                    v1 = make_float4(__ldg(src + 4*bf_tot_cols), __ldg(src + 5*bf_tot_cols), __ldg(src + 6*bf_tot_cols), __ldg(src + 7*bf_tot_cols));
                }
                smem_bf4[(pair * 6 + l * 2 + 0) * SUBWARP + q] = v0;
                smem_bf4[(pair * 6 + l * 2 + 1) * SUBWARP + q] = v1;
            }
        }
        __syncthreads();
    } else if constexpr (SMEM_C) {
        for (int idx = threadIdx.x; idx < c2_elems; idx += 128) smem_c[idx] = __ldg(C2 + idx);
        if constexpr (REM_BF) {
            float* smem_bf = smem_c + c2_elems;
            for (int idx = threadIdx.x; idx < cbf_elems; idx += 128) smem_bf[idx] = __ldg(Cbf + idx);
        }
        __syncthreads();
    }
    const int sid = threadIdx.x / SUBWARP;
    const int slane = threadIdx.x & (SUBWARP - 1);
    const unsigned smask = (SUBWARP == 8) ? (0xffu << ((sid & 3) * 8)) : ((SUBWARP == 16) ? ((sid & 1) ? 0xffff0000u : 0x0000ffffu) : 0xffffffffu);
    const int j = blockIdx.x * NSUB + sid;
    if (j >= N) return;
    const int z_j = species[j];
    const int eb = row_ptr[j], ee = row_end[j];
    const bool active_q = (slane < n_msg);
    const float f0_j = REM_BF ? __ldg(f0 + j) : 0.0f;
    const float* C2_base = SMEM_C ? smem_c : C2;
    const float* Cbf_base = REM_BF ? (SMEM_C ? (smem_c + c2_elems) : Cbf) : nullptr;

    float i0_raw = 0.0f, i1_0_raw = 0.0f, i1_1_raw = 0.0f, i1_2_raw = 0.0f;
    float i2_0_raw = 0.0f, i2_1_raw = 0.0f, i2_2_raw = 0.0f, i2_3_raw = 0.0f, i2_4_raw = 0.0f;
    if (active_q) {
        i0_raw = __ldg(I_node.p[0] + (int64_t)j * n_msg + slane);
        const float* pI1 = I_node.p[1] + (int64_t)j * 3 * n_msg + slane;
        i1_0_raw = __ldg(pI1); i1_1_raw = __ldg(pI1 + n_msg); i1_2_raw = __ldg(pI1 + 2 * n_msg);
        const float* pI2 = I_node.p[2] + (int64_t)j * 5 * n_msg + slane;
        i2_0_raw = __ldg(pI2); i2_1_raw = __ldg(pI2 + n_msg); i2_2_raw = __ldg(pI2 + 2*n_msg); i2_3_raw = __ldg(pI2 + 3*n_msg); i2_4_raw = __ldg(pI2 + 4*n_msg);
    }
    if (slane < 3) s_sf[sid][slane] = (FT)0;
    float acc_di0 = 0.0f, acc_di1_0 = 0.0f, acc_di1_1 = 0.0f, acc_di1_2 = 0.0f;
    float acc_di2_0 = 0.0f, acc_di2_1 = 0.0f, acc_di2_2 = 0.0f, acc_di2_3 = 0.0f, acc_di2_4 = 0.0f;
    float acc_df0 = 0.0f;
    double v0 = 0.0, v1 = 0.0, v2 = 0.0, v3 = 0.0, v4 = 0.0, v5 = 0.0;

    for (int eb_b = eb; eb_b < ee; eb_b += EBATCH) {
        const int bcnt = (ee - eb_b < EBATCH) ? (ee - eb_b) : EBATCH;
        if (slane < bcnt) {
            const int e = eb_b + slane;
            const float4 vl_rev = __ldg(vec_len + e);
            const float4 vl_fwd = make_float4(-vl_rev.x, -vl_rev.y, -vl_rev.z, vl_rev.w);
            const int i_nb = __ldg(senders + e);
            const float r = fmaxf(vl_rev.w, 1e-8f);
            s_vl[sid][slane] = vl_fwd;
            s_i[sid][slane] = i_nb;
            s_pair[sid][slane] = __ldg(species + i_nb) * S + z_j;
            if constexpr (NB_MAX == 8) {
                float4 g03, g47, dg03, dg47;
                eval_cheb8_f4<true>(r, r_max2, g03, g47, dg03, dg47);
                float* gs = s_g[sid][slane]; float* dgs = s_dg[sid][slane];
                gs[0]=g03.x; gs[1]=g03.y; gs[2]=g03.z; gs[3]=g03.w; gs[4]=g47.x; gs[5]=g47.y; gs[6]=g47.z; gs[7]=g47.w;
                dgs[0]=dg03.x; dgs[1]=dg03.y; dgs[2]=dg03.z; dgs[3]=dg03.w; dgs[4]=dg47.x; dgs[5]=dg47.y; dgs[6]=dg47.z; dgs[7]=dg47.w;
            } else {
                eval_cheb<true>(r, r_max2, n_base2, s_g[sid][slane], s_dg[sid][slane]);
            }
            if constexpr (DUAL_G && REM_BF && SUBWARP == 8) {
                eval_cheb<true>(r, r_max1, n_base1, s_g1[sid][slane], s_dg1[sid][slane]);
            }
        } else if (slane >= EBATCH && slane < EBATCH + bcnt) {
            const int bi = slane - EBATCH;
            const float4 vl_rev = __ldg(vec_len + eb_b + bi);
            const float r = fmaxf(vl_rev.w, 1e-8f);
            edge_sh9(-vl_rev.x, -vl_rev.y, -vl_rev.z, r, s_Y[sid][bi]);
        } else if constexpr (DUAL_G && REM_BF && SUBWARP >= 16) {
            if (slane >= 2 * EBATCH && slane < 2 * EBATCH + bcnt) {
                const int bi = slane - 2 * EBATCH;
                const float4 vl_rev = __ldg(vec_len + eb_b + bi);
                const float r = fmaxf(vl_rev.w, 1e-8f);
                eval_cheb<true>(r, r_max1, n_base1, s_g1[sid][bi], s_dg1[sid][bi]);
            }
        }
        __syncwarp(smask);

        for (int bi = 0; bi < bcnt; ++bi) {
            const int i_nb = s_i[sid][bi];
            const int pair = s_pair[sid][bi];
            float er_lane = 0.0f;
            float dY1 = 0.0f, dY2 = 0.0f, dY3 = 0.0f, dY4 = 0.0f, dY5 = 0.0f, dY6 = 0.0f, dY7 = 0.0f, dY8 = 0.0f;
            if (active_q) {
                const float* gk  = s_g[sid][bi];
                const float* dgk = s_dg[sid][bi];
                const float* Yk  = s_Y[sid][bi];
                const float* C2p = C2_base + (int64_t)pair * n_base2 * l2_tot_cols + slane;
                float r2_0 = 0.0f, r2_1 = 0.0f, r2_2 = 0.0f;
                float dr2_0 = 0.0f, dr2_1 = 0.0f, dr2_2 = 0.0f;
                if constexpr (F4_SMEM) {
                    const float4 g03 = make_float4(gk[0], gk[1], gk[2], gk[3]);
                    const float4 g47 = make_float4(gk[4], gk[5], gk[6], gk[7]);
                    const float4 d03 = make_float4(dgk[0], dgk[1], dgk[2], dgk[3]);
                    const float4 d47 = make_float4(dgk[4], dgk[5], dgk[6], dgk[7]);
                    const float4* cp4 = smem_c4 + pair * 6 * SUBWARP + slane;
                    const float4 c0a = cp4[0 * SUBWARP], c0b = cp4[1 * SUBWARP];
                    r2_0 = v1_dot4(c0a, g03) + v1_dot4(c0b, g47); dr2_0 = v1_dot4(c0a, d03) + v1_dot4(c0b, d47);
                    const float4 c1a = cp4[2 * SUBWARP], c1b = cp4[3 * SUBWARP];
                    r2_1 = v1_dot4(c1a, g03) + v1_dot4(c1b, g47); dr2_1 = v1_dot4(c1a, d03) + v1_dot4(c1b, d47);
                    const float4 c2a = cp4[4 * SUBWARP], c2b = cp4[5 * SUBWARP];
                    r2_2 = v1_dot4(c2a, g03) + v1_dot4(c2b, g47); dr2_2 = v1_dot4(c2a, d03) + v1_dot4(c2b, d47);
                } else {
                    auto acc_c2 = [&](int k) {
                        const float gv = gk[k], dgv = dgk[k]; const float* rrow = C2p + k * l2_tot_cols;
                        const float c0 = SMEM_C ? rrow[0]         : __ldg(rrow);
                        const float c1 = SMEM_C ? rrow[n_msg]     : __ldg(rrow + n_msg);
                        const float c2 = SMEM_C ? rrow[2 * n_msg] : __ldg(rrow + 2 * n_msg);
                        r2_0 = fmaf(c0, gv, r2_0); dr2_0 = fmaf(c0, dgv, dr2_0);
                        r2_1 = fmaf(c1, gv, r2_1); dr2_1 = fmaf(c1, dgv, dr2_1);
                        r2_2 = fmaf(c2, gv, r2_2); dr2_2 = fmaf(c2, dgv, dr2_2);
                    };
                    if constexpr (NB_MAX == 8) {
                        #pragma unroll
                        for (int k = 0; k < 8; ++k) acc_c2(k);
                    } else {
                        if (n_base2 == 12)      {
                            #pragma unroll 4
                            for (int k = 0; k < 12; ++k) acc_c2(k); }
                        else if (n_base2 == 14) {
                            #pragma unroll 4
                            for (int k = 0; k < 14; ++k) acc_c2(k); }
                        else if (n_base2 == 16) {
                            #pragma unroll 4
                            for (int k = 0; k < 16; ++k) acc_c2(k); }
                        else { for (int k = 0; k < n_base2; ++k) acc_c2(k); }
                    }
                }

                float rbf0 = 0.0f, rbf1 = 0.0f, drbf0 = 0.0f, drbf1 = 0.0f; float rbf2 = 0.0f, drbf2 = 0.0f;
                if constexpr (REM_BF) {
                    if constexpr (F4_SMEM) {
                        const float4 g03 = make_float4(gk[0], gk[1], gk[2], gk[3]);
                        const float4 g47 = make_float4(gk[4], gk[5], gk[6], gk[7]);
                        const float4 d03 = make_float4(dgk[0], dgk[1], dgk[2], dgk[3]);
                        const float4 d47 = make_float4(dgk[4], dgk[5], dgk[6], dgk[7]);
                        const float4* bp4 = smem_bf4 + pair * 6 * SUBWARP + slane;
                        const float4 b0a = bp4[0 * SUBWARP], b0b = bp4[1 * SUBWARP];
                        rbf0 = v1_dot4(b0a, g03) + v1_dot4(b0b, g47); drbf0 = v1_dot4(b0a, d03) + v1_dot4(b0b, d47);
                        const float4 b1a = bp4[2 * SUBWARP], b1b = bp4[3 * SUBWARP];
                        rbf1 = v1_dot4(b1a, g03) + v1_dot4(b1b, g47); drbf1 = v1_dot4(b1a, d03) + v1_dot4(b1b, d47);
                        const float4 b2a = bp4[4 * SUBWARP], b2b = bp4[5 * SUBWARP];
                        rbf2 = v1_dot4(b2a, g03) + v1_dot4(b2b, g47); drbf2 = v1_dot4(b2a, d03) + v1_dot4(b2b, d47);
                    } else {
                        const float* gkb  = DUAL_G ? s_g1[sid][bi]  : gk;
                        const float* dgkb = DUAL_G ? s_dg1[sid][bi] : dgk;
                        const float* Cbp = Cbf_base + (int64_t)pair * n_base1 * bf_tot_cols + slane;
                        auto acc_bf = [&](int k) {
                            const float gv = gkb[k], dgv = dgkb[k]; const float* rrow = Cbp + k * bf_tot_cols;
                            const float b0 = SMEM_C ? rrow[0]     : __ldg(rrow);
                            const float b1 = SMEM_C ? rrow[n_msg] : __ldg(rrow + n_msg);
                            rbf0 = fmaf(b0, gv, rbf0); drbf0 = fmaf(b0, dgv, drbf0);
                            rbf1 = fmaf(b1, gv, rbf1); drbf1 = fmaf(b1, dgv, drbf1);
                            const float b2 = SMEM_C ? rrow[2*n_msg] : __ldg(rrow + 2*n_msg);
                            rbf2 = fmaf(b2, gv, rbf2); drbf2 = fmaf(b2, dgv, drbf2);
                        };
                        if constexpr (!DUAL_G && NB_MAX == 8) {
                            #pragma unroll
                            for (int k = 0; k < 8; ++k) acc_bf(k);
                        } else {
                            if (n_base1 == 8)       {
                                #pragma unroll
                                for (int k = 0; k < 8; ++k) acc_bf(k); }
                            else if (n_base1 == 12) {
                                #pragma unroll 4
                                for (int k = 0; k < 12; ++k) acc_bf(k); }
                            else if (n_base1 == 14) {
                                #pragma unroll 4
                                for (int k = 0; k < 14; ++k) acc_bf(k); }
                            else if (n_base1 == 16) {
                                #pragma unroll 4
                                for (int k = 0; k < 16; ++k) acc_bf(k); }
                            else { for (int k = 0; k < n_base1; ++k) acc_bf(k); }
                        }
                    }
                }
                const float i0_0 = i0_raw   - (REM_BF ? (f0_j * rbf0) * Yk[0] : 0.0f);
                const float i1_0 = i1_0_raw - (REM_BF ? (f0_j * rbf1) * Yk[1] : 0.0f);
